window.TKT_TOPICS={"01_Fundamentals":"Fundamentals","02_Equilibrium_and_Newton":"Equilibrium & Newton","03_Path_following":"Path following & Riks","04_Plasticity":"Elasto-plasticity","05_Structural_dynamics_and_mass":"Dynamics & mass","06_Explicit_integration":"Explicit integration","07_Implicit_integration":"Implicit integration","08_Nonlinear_dynamics_checks":"Nonlinear dynamics","09_Constraints":"Kinematic constraints","10_Contact":"Contact mechanics","11_Finite_strain_and_TL_elements":"Finite strain & TL elements","12_Stress_stiffness_buckling":"Stress stiffness & buckling","13_Exam_practice_and_Abaqus":"Abaqus & exam practice"};
window.TKT_QUESTIONS=[{"id":"c000","topic":"01_Fundamentals","question":"What is the main distinction between linear and nonlinear FEA?","answer":"In linear FEA, stiffness and response are independent of displacement/load level; nonlinear FEA updates the state and generally requires iterative equilibrium.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Linear FEA uses fixed stiffness; nonlinear FEA updates the response state.","Nonlinear FEA always uses a finer mesh.","Linear FEA can model plastic yielding without iteration.","Nonlinear FEA neglects displacement-dependent stiffness."],"correct":0},{"id":"c001","topic":"01_Fundamentals","question":"Name the four main sources of nonlinearity in FEA.","answer":"Geometric effects; material constitutive behavior; displacement boundary conditions/contact; load or force boundary conditions.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Geometric, material, displacement-BC, and force-BC nonlinearities.","Elastic, plastic, viscous, and thermal strains only.","Mass, damping, stiffness, and eigenfrequencies.","Geometry, integration, mesh density, and shape functions."],"correct":0},{"id":"c002","topic":"01_Fundamentals","question":"What causes geometric nonlinearity?","answer":"Large displacements/rotations, changing geometry, and stress-dependent stiffness even when material strains are small.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Large displacements/rotations and changes in geometry or stress stiffness.","Only a nonlinear stress–strain constitutive law.","A mesh with more than one finite element.","Always using a nonzero damping matrix."],"correct":0},{"id":"c003","topic":"01_Fundamentals","question":"Give two examples of material nonlinearity.","answer":"Plastic yielding with hardening, and nonlinear elasticity (also damage or viscoelastic response).","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Plastic yielding with hardening, and nonlinear elasticity (also damage or viscoelastic response).","Element size can affect local yielding, contact, buckling modes, stiffness, and predicted failure loads.","Large displacements/rotations, changing geometry, and stress-dependent stiffness even when material strains are small.","To check geometry, supports, mesh, and load transfer before adding nonlinear effects."],"correct":0},{"id":"c004","topic":"01_Fundamentals","question":"Why is contact a nonlinear boundary condition?","answer":"The active constraints and contact forces change when surfaces touch, separate, or slide.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Contact constraints switch on or off as surfaces touch or separate.","Contact is always represented with a nonlinear material law.","Contact loads cannot transfer force between bodies.","The mesh must be regenerated at each increment."],"correct":0},{"id":"c005","topic":"01_Fundamentals","question":"What is a nonconservative force in nonlinear FEA?","answer":"A load whose direction or point of action changes with the deformation so that no single displacement-independent potential exists.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["A load that changes with deformation and lacks a global load potential.","A fixed-direction dead load independent of deformation.","A constant gravitational body force.","Any load that varies sinusoidally with time."],"correct":0},{"id":"c006","topic":"01_Fundamentals","question":"What does the equilibrium path represent?","answer":"All pairs of displacement state and load parameter satisfying the nonlinear equilibrium equations.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["All displacement–load states that satisfy equilibrium.","All possible FE meshes for a structure.","The time history of a single element stress.","Only the unstable states past buckling."],"correct":0},{"id":"c007","topic":"01_Fundamentals","question":"What is the fundamental equilibrium path?","answer":"The primary equilibrium branch emerging from the reference, normally unloaded configuration.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["The primary equilibrium branch emerging from the reference, normally unloaded configuration.","An additional equilibrium branch, commonly arising from a bifurcation point.","All pairs of displacement state and load parameter satisfying the nonlinear equilibrium equations.","The current response depends on the history of loading and internal variables, not just the final load."],"correct":0},{"id":"c008","topic":"01_Fundamentals","question":"What is a secondary equilibrium path?","answer":"An additional equilibrium branch, commonly arising from a bifurcation point.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["An additional equilibrium branch, commonly arising from a bifurcation point.","The primary equilibrium branch emerging from the reference, normally unloaded configuration.","All pairs of displacement state and load parameter satisfying the nonlinear equilibrium equations.","A rapid change between equilibrium configurations near a limit point, often with a load drop."],"correct":0},{"id":"c009","topic":"01_Fundamentals","question":"What is snap-through?","answer":"A rapid change between equilibrium configurations near a limit point, often with a load drop.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["A sudden transition between equilibrium configurations near a limit point.","An always-linear reduction in stiffness.","Plastic flow without any geometric deformation.","High-frequency vibration from incorrect mass lumping."],"correct":0},{"id":"c010","topic":"01_Fundamentals","question":"What is nonlinear stiffening?","answer":"The tangent stiffness increases as the structure deforms; a sagging cable stiffens as axial tension develops.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["The tangent stiffness increases as the structure deforms; a sagging cable stiffens as axial tension develops.","The stiffness or governing equations change with the state, so adding separate responses need not produce the combined response.","Global force balance; mesh/time-step sensitivity; plausible energy balance and deformation mode.","A load/history parameter identifying solution states; it need not represent physical elapsed time."],"correct":0},{"id":"c011","topic":"01_Fundamentals","question":"Why should a linear analysis usually precede nonlinear analysis?","answer":"To check geometry, supports, mesh, and load transfer before adding nonlinear effects.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["To validate supports, loading, and mesh before adding nonlinear effects.","Because a linear solution must equal the final nonlinear solution.","To eliminate the need for a mesh study.","Because linear FEA can always predict collapse accurately."],"correct":0},{"id":"c012","topic":"01_Fundamentals","question":"Why is a mesh-convergence study important in nonlinear FEA?","answer":"Element size can affect local yielding, contact, buckling modes, stiffness, and predicted failure loads.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Element size can affect local yielding, contact, buckling modes, stiffness, and predicted failure loads.","The tangent stiffness increases as the structure deforms; a sagging cable stiffens as axial tension develops.","The tangent relation is only locally accurate; a large response is built from smaller equilibrated changes.","To check geometry, supports, mesh, and load transfer before adding nonlinear effects."],"correct":0},{"id":"c013","topic":"01_Fundamentals","question":"Why can a numerically converged nonlinear solution still be wrong?","answer":"Equilibrium convergence does not ensure correct material properties, boundary conditions, mesh resolution, or physical modeling.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Convergence enforces equations, not whether the model represents reality.","Converged solutions necessarily use exact geometry.","Convergence proves all material parameters are correct.","Numerical convergence removes discretization error."],"correct":0},{"id":"c014","topic":"01_Fundamentals","question":"Why are incremental solution procedures necessary in nonlinear FEA?","answer":"The tangent relation is only locally accurate; a large response is built from smaller equilibrated changes.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["The tangent relation is only locally accurate; a large response is built from smaller equilibrated changes.","A load whose direction or point of action changes with the deformation so that no single displacement-independent potential exists.","Element size can affect local yielding, contact, buckling modes, stiffness, and predicted failure loads.","The current response depends on the history of loading and internal variables, not just the final load."],"correct":0},{"id":"c015","topic":"01_Fundamentals","question":"What is meant by path dependence?","answer":"The current response depends on the history of loading and internal variables, not just the final load.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Response depends on loading history and evolving internal variables.","Response depends only on the final external load.","The structure always follows the shortest displacement path.","The initial FE mesh determines the entire loading history."],"correct":0},{"id":"c016","topic":"01_Fundamentals","question":"Can a material be linearly elastic in a geometrically nonlinear model?","answer":"Yes. Constitutive behavior may be linear while finite rotations or deformed geometry make structural equilibrium nonlinear.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Yes. Constitutive behavior may be linear while finite rotations or deformed geometry make structural equilibrium nonlinear.","Large displacements/rotations, changing geometry, and stress-dependent stiffness even when material strains are small.","Plastic yielding with hardening, and nonlinear elasticity (also damage or viscoelastic response).","A load whose direction or point of action changes with the deformation so that no single displacement-independent potential exists."],"correct":0},{"id":"c017","topic":"01_Fundamentals","question":"Why is superposition generally invalid for nonlinear structural response?","answer":"The stiffness or governing equations change with the state, so adding separate responses need not produce the combined response.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["The stiffness or governing equations change with the state, so adding separate responses need not produce the combined response.","A load whose direction or point of action changes with the deformation so that no single displacement-independent potential exists.","The tangent stiffness increases as the structure deforms; a sagging cable stiffens as axial tension develops.","In linear FEA, stiffness and response are independent of displacement/load level; nonlinear FEA updates the state and generally requires iterative equilibrium."],"correct":0},{"id":"c018","topic":"01_Fundamentals","question":"What are three useful checks for a nonlinear FE result?","answer":"Global force balance; mesh/time-step sensitivity; plausible energy balance and deformation mode.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["Global force balance; mesh/time-step sensitivity; plausible energy balance and deformation mode.","To check geometry, supports, mesh, and load transfer before adding nonlinear effects.","A rapid change between equilibrium configurations near a limit point, often with a load drop.","Plastic yielding with hardening, and nonlinear elasticity (also damage or viscoelastic response)."],"correct":0},{"id":"c019","topic":"01_Fundamentals","question":"What is pseudotime in quasi-static nonlinear analysis?","answer":"A load/history parameter identifying solution states; it need not represent physical elapsed time.","source":"Lecture 1; Lecture 14; Exercise 1; Exam 2019 P1","options":["A load/history parameter identifying solution states; it need not represent physical elapsed time.","To check geometry, supports, mesh, and load transfer before adding nonlinear effects.","All pairs of displacement state and load parameter satisfying the nonlinear equilibrium equations.","Global force balance; mesh/time-step sensitivity; plausible energy balance and deformation mode."],"correct":0},{"id":"c020","topic":"02_Equilibrium_and_Newton","question":"State the global nonlinear equilibrium equation.","answer":"\\(\\mathbf R_{res}=\\mathbf R_{ext}-\\mathbf R_{int}=\\mathbf 0\\).","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["R_res = R_ext − R_int = 0.","R_res = M D¨ + C D˙ + K D.","R_res = R_ext + R_int = 0.","R_res = K_t + K_g = 0."],"correct":0},{"id":"c021","topic":"02_Equilibrium_and_Newton","question":"What is the residual force vector?","answer":"The unbalanced force, external minus internal; a converged equilibrium state has negligible residual.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["The external force minus the internal force at a given state.","The absolute value of every applied nodal force.","The strain energy stored in an element.","The fixed reference stiffness of the model."],"correct":0},{"id":"c022","topic":"02_Equilibrium_and_Newton","question":"How is the internal FE force vector obtained from stresses?","answer":"\\(\\mathbf r_{int}=\\int_V\\mathbf B^T\\boldsymbol\\sigma\\,dV\\) for the small-strain formulation.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["\\(\\mathbf r_{int}=\\int_V\\mathbf B^T\\boldsymbol\\sigma\\,dV\\) for the small-strain formulation.","\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D\\) for a fixed dead-load vector.","\\(\\mathbf R_{res}=\\mathbf R_{ext}-\\mathbf R_{int}=\\mathbf 0\\).","The unbalanced force, external minus internal; a converged equilibrium state has negligible residual."],"correct":0},{"id":"c023","topic":"02_Equilibrium_and_Newton","question":"What does the strain-displacement matrix B do?","answer":"Maps element nodal displacements (or increments) into the chosen strain measure (or increment).","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["It converts nodal displacement quantities into strains.","It transforms stresses into nodal coordinates only.","It converts natural frequencies to mode shapes.","It imposes contact tractions directly."],"correct":0},{"id":"c024","topic":"02_Equilibrium_and_Newton","question":"What is total potential energy for a conservative static system?","answer":"\\(\\Pi=U+\\Omega\\), where \\(U\\) is stored strain energy and \\(\\Omega\\) is external-load potential.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Strain energy plus the external load potential: Π = U + Ω.","Kinetic energy minus damping energy only.","Total displacement multiplied by tangent stiffness.","The eigenvalues of the element mass matrix."],"correct":0},{"id":"c025","topic":"02_Equilibrium_and_Newton","question":"State the principle of stationary potential energy.","answer":"At equilibrium, admissible variations satisfy \\(\\delta\\Pi=0\\); thus the first derivative with respect to free DOFs vanishes.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Equilibrium requires the first variation of Π to vanish.","Equilibrium requires the total potential to be zero.","Equilibrium requires strain energy to vanish.","Equilibrium requires the second variation to vanish everywhere."],"correct":0},{"id":"c026","topic":"02_Equilibrium_and_Newton","question":"How is internal force derived from strain energy?","answer":"\\(\\mathbf R_{int}=\\partial U/\\partial\\mathbf D\\).","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Differentiate U with respect to displacement DOFs.","Differentiate load parameter with respect to time.","Integrate the mass matrix over velocity.","Take the determinant of the tangent stiffness."],"correct":0},{"id":"c027","topic":"02_Equilibrium_and_Newton","question":"How is external load related to external-load potential?","answer":"\\(\\mathbf R_{ext}=-\\partial\\Omega/\\partial\\mathbf D\\) when \\(\\Omega\\) is defined as the negative work of the loads.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["\\(\\mathbf R_{ext}=-\\partial\\Omega/\\partial\\mathbf D\\) when \\(\\Omega\\) is defined as the negative work of the loads.","\\(\\mathbf R_{int}=\\partial U/\\partial\\mathbf D\\).","\\(\\mathbf R_{res}=\\mathbf R_{ext}-\\mathbf R_{int}=\\mathbf 0\\).","Check the incremental imbalance work, e.g. \\(|\\Delta\\mathbf D^T\\mathbf R_{res}|\\), against a suitable energy scale."],"correct":0},{"id":"c028","topic":"02_Equilibrium_and_Newton","question":"How can tangent stiffness be obtained from internal force?","answer":"\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D\\) for a fixed dead-load vector.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Differentiate the internal nodal force vector with respect to DOFs.","Divide the internal force vector by displacement componentwise.","Take the inverse of the consistent mass matrix.","Differentiate the nodal positions with respect to physical time."],"correct":0},{"id":"c029","topic":"02_Equilibrium_and_Newton","question":"How is tangent stiffness related to total potential energy?","answer":"For conservative dead loading, \\(\\mathbf K_t=\\partial^2\\Pi/\\partial\\mathbf D^2\\).","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["For conservative dead loading, \\(\\mathbf K_t=\\partial^2\\Pi/\\partial\\mathbf D^2\\).","\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D\\) for a fixed dead-load vector.","\\(\\Pi=U+\\Omega\\), where \\(U\\) is stored strain energy and \\(\\Omega\\) is external-load potential.","\\(\\mathbf K_t(\\mathbf D_i)\\,\\Delta\\mathbf D_i=\\mathbf R_{res}(\\mathbf D_i)\\)."],"correct":0},{"id":"c030","topic":"02_Equilibrium_and_Newton","question":"Why do we linearize nonlinear equilibrium?","answer":"To replace a local nonlinear correction with a solvable linear system at each iteration.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["To solve a nonlinear equilibrium equation using local linear corrections.","To remove nonlinearity permanently from the material model.","To guarantee one iteration reaches exact equilibrium.","To avoid computing element internal forces."],"correct":0},{"id":"c031","topic":"02_Equilibrium_and_Newton","question":"Write the Newton displacement-correction equation.","answer":"\\(\\mathbf K_t(\\mathbf D_i)\\,\\Delta\\mathbf D_i=\\mathbf R_{res}(\\mathbf D_i)\\).","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["K_t ΔD = R_ext − R_int.","M D¨ + C D˙ + K D = 0.","K_t ΔD = R_ext + R_int.","K_m + λ K_g = 0."],"correct":0},{"id":"c032","topic":"02_Equilibrium_and_Newton","question":"How is the displacement updated during Newton iteration?","answer":"\\(\\mathbf D_{i+1}=\\mathbf D_i+\\Delta\\mathbf D_i\\).","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["\\(\\mathbf D_{i+1}=\\mathbf D_i+\\Delta\\mathbf D_i\\).","\\(\\mathbf R_{int}=\\partial U/\\partial\\mathbf D\\).","The tangent stiffness is recomputed for every equilibrium iteration.","\\(\\mathbf R_{res}=\\mathbf R_{ext}-\\mathbf R_{int}=\\mathbf 0\\)."],"correct":0},{"id":"c033","topic":"02_Equilibrium_and_Newton","question":"What is the role of the predictor step?","answer":"Predict the new state from the previous converged state, often using tangent stiffness and a load increment.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["An initial displacement estimate for the next load increment.","A final exact solution requiring no correction.","A recalculation of the consistent mass matrix only.","An imposed zero-residual equilibrium state."],"correct":0},{"id":"c034","topic":"02_Equilibrium_and_Newton","question":"What is the role of the corrector steps?","answer":"Apply Newton iterations until the predicted state satisfies equilibrium to the prescribed tolerance.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Reduce the residual by iteratively updating displacements.","Increase the residual to reveal instability.","Adjust only the mass density during each step.","Change the prescribed boundary conditions to zero."],"correct":0},{"id":"c035","topic":"02_Equilibrium_and_Newton","question":"What distinguishes full Newton-Raphson?","answer":"The tangent stiffness is recomputed for every equilibrium iteration.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["It recomputes the tangent stiffness every iteration.","It computes tangent stiffness only in the first increment.","It replaces force equilibrium with energy minimization only.","It performs no correction iterations."],"correct":0},{"id":"c036","topic":"02_Equilibrium_and_Newton","question":"What distinguishes modified Newton-Raphson?","answer":"The stiffness is held fixed over iterations within an increment, and is generally updated at a new increment.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["It reuses the tangent stiffness over several iterations.","It recomputes the tangent stiffness at every correction.","It is identical to central-difference time integration.","It requires a diagonal tangent stiffness."],"correct":0},{"id":"c037","topic":"02_Equilibrium_and_Newton","question":"Why is full Newton often faster near the solution?","answer":"With a consistent nonsingular tangent and smooth equations, local convergence is quadratic.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Updated tangents can yield local quadratic convergence.","It does not need to evaluate the residual.","It ignores all nonlinear material behavior.","Its time increment is always smaller."],"correct":0},{"id":"c038","topic":"02_Equilibrium_and_Newton","question":"Why can modified Newton cost less per iteration?","answer":"It reuses a stiffness factorization instead of assembling/factorizing a new tangent every iteration.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["It reuses a stiffness factorization instead of assembling/factorizing a new tangent every iteration.","The stiffness is held fixed over iterations within an increment, and is generally updated at a new increment.","The tangent stiffness is recomputed for every equilibrium iteration.","Its convergence is usually linear and may require more iterations or smaller load increments."],"correct":0},{"id":"c039","topic":"02_Equilibrium_and_Newton","question":"What is the main disadvantage of modified Newton?","answer":"Its convergence is usually linear and may require more iterations or smaller load increments.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Its convergence is usually linear and may require more iterations or smaller load increments.","The stiffness is held fixed over iterations within an increment, and is generally updated at a new increment.","It reuses a stiffness factorization instead of assembling/factorizing a new tangent every iteration.","Use smaller load steps, line search/damping, or a suitable path-following method."],"correct":0},{"id":"c040","topic":"02_Equilibrium_and_Newton","question":"What is a quasi-Newton method?","answer":"An iterative method that approximates or updates the tangent/inverse tangent without fully recomputing it.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["An approximate tangent update based on iteration history.","A procedure that always uses the exact Hessian.","An explicit time integration method for impacts only.","A method that sets all stiffness terms to unity."],"correct":0},{"id":"c041","topic":"02_Equilibrium_and_Newton","question":"What is forward Euler load incrementation?","answer":"A predictor-only method using the current tangent for each load increment, without iterative equilibrium correction.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["A predictor-only method using the current tangent for each load increment, without iterative equilibrium correction.","Predict the new state from the previous converged state, often using tangent stiffness and a load increment.","An iterative method that approximates or updates the tangent/inverse tangent without fully recomputing it.","\\(\\mathbf R_{ext}=-\\partial\\Omega/\\partial\\mathbf D\\) when \\(\\Omega\\) is defined as the negative work of the loads."],"correct":0},{"id":"c042","topic":"02_Equilibrium_and_Newton","question":"Why does pure incremental Euler loading accumulate error?","answer":"Each step follows a tangent approximation but never corrects the resulting force imbalance.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Each step follows a tangent approximation but never corrects the resulting force imbalance.","A small displacement correction does not always guarantee a small force imbalance, and vice versa.","With a consistent nonsingular tangent and smooth equations, local convergence is quadratic.","The secant is force/displacement; the Newton tangent is the derivative of force with respect to displacement."],"correct":0},{"id":"c043","topic":"02_Equilibrium_and_Newton","question":"What is quadratic convergence in Newton-Raphson?","answer":"Near the solution, the error at the next iteration is proportional to roughly the square of the current error.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["The error roughly squares each iteration near a regular root.","The error decreases by a fixed amount each iteration.","The number of iterations doubles each load step.","The residual is always zero after two iterations."],"correct":0},{"id":"c044","topic":"02_Equilibrium_and_Newton","question":"Why is a consistent tangent preferable to a secant tangent?","answer":"It is the derivative of the implemented force update, supporting much faster Newton convergence.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["It is the derivative of the implemented force update, supporting much faster Newton convergence.","The secant is force/displacement; the Newton tangent is the derivative of force with respect to displacement.","The displacement correction cannot be uniquely obtained from the ordinary linear solve.","A small displacement correction does not always guarantee a small force imbalance, and vice versa."],"correct":0},{"id":"c045","topic":"02_Equilibrium_and_Newton","question":"Why is a singular tangent stiffness problematic for standard Newton?","answer":"The displacement correction cannot be uniquely obtained from the ordinary linear solve.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["The Newton correction may be nonunique or impossible to solve.","It guarantees that the equilibrium solution is stable.","It means the mass matrix must also be singular.","It eliminates all possibility of a bifurcation."],"correct":0},{"id":"c046","topic":"02_Equilibrium_and_Newton","question":"How can a Newton iteration be stabilized when far from equilibrium?","answer":"Use smaller load steps, line search/damping, or a suitable path-following method.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Use smaller load steps, line search/damping, or a suitable path-following method.","\\(\\mathbf D_{i+1}=\\mathbf D_i+\\Delta\\mathbf D_i\\).","Its convergence is usually linear and may require more iterations or smaller load increments.","It reuses a stiffness factorization instead of assembling/factorizing a new tangent every iteration."],"correct":0},{"id":"c047","topic":"02_Equilibrium_and_Newton","question":"What is a force-residual convergence test?","answer":"Check that \\(\\|\\mathbf R_{res}\\|\\) is small relative to an appropriate force scale.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Check that the unbalanced force is sufficiently small.","Check that all displacement increments are positive.","Check that the element stress is exactly zero.","Check that the mass matrix is diagonal."],"correct":0},{"id":"c048","topic":"02_Equilibrium_and_Newton","question":"What is a displacement-correction convergence test?","answer":"Check that \\(\\|\\Delta\\mathbf D\\|\\) is sufficiently small relative to a meaningful displacement scale.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Check that \\(\\|\\Delta\\mathbf D\\|\\) is sufficiently small relative to a meaningful displacement scale.","Check that \\(\\|\\mathbf R_{res}\\|\\) is small relative to an appropriate force scale.","Check the incremental imbalance work, e.g. \\(|\\Delta\\mathbf D^T\\mathbf R_{res}|\\), against a suitable energy scale.","\\(\\mathbf K_t(\\mathbf D_i)\\,\\Delta\\mathbf D_i=\\mathbf R_{res}(\\mathbf D_i)\\)."],"correct":0},{"id":"c049","topic":"02_Equilibrium_and_Newton","question":"What is an energy-based convergence test?","answer":"Check the incremental imbalance work, e.g. \\(|\\Delta\\mathbf D^T\\mathbf R_{res}|\\), against a suitable energy scale.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Check the incremental imbalance work, e.g. \\(|\\Delta\\mathbf D^T\\mathbf R_{res}|\\), against a suitable energy scale.","Check that \\(\\|\\mathbf R_{res}\\|\\) is small relative to an appropriate force scale.","Check that \\(\\|\\Delta\\mathbf D\\|\\) is sufficiently small relative to a meaningful displacement scale.","\\(\\mathbf K_t(\\mathbf D_i)\\,\\Delta\\mathbf D_i=\\mathbf R_{res}(\\mathbf D_i)\\)."],"correct":0},{"id":"c050","topic":"02_Equilibrium_and_Newton","question":"Why should convergence tolerances not be extremely loose?","answer":"A visible residual may produce an inaccurate equilibrium path, stresses, or stability prediction.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["A visible residual may produce an inaccurate equilibrium path, stresses, or stability prediction.","Round-off and numerical noise may cause wasted iterations or false nonconvergence.","A small displacement correction does not always guarantee a small force imbalance, and vice versa.","Maps element nodal displacements (or increments) into the chosen strain measure (or increment)."],"correct":0},{"id":"c051","topic":"02_Equilibrium_and_Newton","question":"Why should convergence tolerances not be unnecessarily tight?","answer":"Round-off and numerical noise may cause wasted iterations or false nonconvergence.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Round-off and numerical noise may cause wasted iterations or false nonconvergence.","A visible residual may produce an inaccurate equilibrium path, stresses, or stability prediction.","Its convergence is usually linear and may require more iterations or smaller load increments.","Check that \\(\\|\\Delta\\mathbf D\\|\\) is sufficiently small relative to a meaningful displacement scale."],"correct":0},{"id":"c052","topic":"02_Equilibrium_and_Newton","question":"Why should multiple convergence measures sometimes be combined?","answer":"A small displacement correction does not always guarantee a small force imbalance, and vice versa.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["A small displacement correction does not always guarantee a small force imbalance, and vice versa.","Each step follows a tangent approximation but never corrects the resulting force imbalance.","Check that \\(\\|\\mathbf R_{res}\\|\\) is small relative to an appropriate force scale.","\\(\\mathbf r_{int}=\\int_V\\mathbf B^T\\boldsymbol\\sigma\\,dV\\) for the small-strain formulation."],"correct":0},{"id":"c053","topic":"02_Equilibrium_and_Newton","question":"How are two nonlinear spring internal forces assembled?","answer":"Compute element nodal forces from each spring elongation and assemble them with the correct signs at shared nodes.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["Compute element nodal forces from each spring elongation and assemble them with the correct signs at shared nodes.","Maps element nodal displacements (or increments) into the chosen strain measure (or increment).","The secant is force/displacement; the Newton tangent is the derivative of force with respect to displacement.","It is the derivative of the implemented force update, supporting much faster Newton convergence."],"correct":0},{"id":"c054","topic":"02_Equilibrium_and_Newton","question":"Why is a secant stiffness not the Newton tangent?","answer":"The secant is force/displacement; the Newton tangent is the derivative of force with respect to displacement.","source":"Lecture 2; Lecture 14; Exercise 1; Exercise 3; Exam 2021 P1; Exam 2022 P1; Exam 2025 P1","options":["The secant is force/displacement; the Newton tangent is the derivative of force with respect to displacement.","It is the derivative of the implemented force update, supporting much faster Newton convergence.","The stiffness is held fixed over iterations within an increment, and is generally updated at a new increment.","\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D\\) for a fixed dead-load vector."],"correct":0},{"id":"c055","topic":"03_Path_following","question":"Define a load limit point on an equilibrium path.","answer":"A point at which the load parameter has a local extremum along the path (dλ/ds = 0).","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["The load parameter has a local extremum along the equilibrium path.","The controlled displacement must be exactly zero.","Two independent equilibrium branches must intersect.","The strain energy becomes zero everywhere."],"correct":0},{"id":"c056","topic":"03_Path_following","question":"Define a turning point for displacement control.","answer":"A point where the controlled displacement reaches a local extremum (dD_control/ds = 0).","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["The controlled displacement has a local extremum along the path.","The reference configuration has zero displacement.","The load multiplier necessarily has a local maximum.","The tangent material stiffness is always positive definite."],"correct":0},{"id":"c057","topic":"03_Path_following","question":"Define a bifurcation point.","answer":"A critical equilibrium point where two or more solution branches intersect.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Two or more equilibrium branches intersect at a critical point.","An equilibrium curve has maximum load but one branch only.","A material first reaches its yield stress.","A numerical iteration fails due to a coarse mesh."],"correct":0},{"id":"c058","topic":"03_Path_following","question":"What is the mathematical signature of a critical equilibrium point?","answer":"\\(\\det\\mathbf K_t=0\\), or equivalently at least one zero eigenvalue of tangent stiffness.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["The tangent stiffness becomes singular (has a zero eigenvalue).","The external load must be exactly zero.","The consistent mass matrix becomes diagonal.","All displacement components reach a maximum."],"correct":0},{"id":"c059","topic":"03_Path_following","question":"Does a singular tangent prove a bifurcation?","answer":"No. Both limit points and bifurcations can have a singular tangent.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["No. Singular stiffness can occur at a limit point too.","Yes. Every singular tangent is a bifurcation.","Yes, but only when mass density is nonzero.","No. Singular stiffness never occurs at bifurcations."],"correct":0},{"id":"c060","topic":"03_Path_following","question":"Why does load control fail at a load limit point?","answer":"The path reverses in load, so load cannot serve as a unique monotonically increasing control parameter.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Load cannot be increased monotonically through a load extremum.","The material stiffness always becomes infinite.","A bifurcation always causes the mass matrix to vanish.","Load control cannot be used for linear problems."],"correct":0},{"id":"c061","topic":"03_Path_following","question":"Why does displacement control fail at a turning point?","answer":"The chosen displacement reverses, so the response cannot be uniquely advanced by prescribing that DOF.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["The chosen displacement reverses, so the response cannot be uniquely advanced by prescribing that DOF.","The path reverses in load, so load cannot serve as a unique monotonically increasing control parameter.","It can follow load-dropping (snap-through) response up to points where the selected displacement ceases to be monotonic.","A critical equilibrium point where two or more solution branches intersect."],"correct":0},{"id":"c062","topic":"03_Path_following","question":"Why is displacement control often more robust than load control?","answer":"It can follow load-dropping (snap-through) response up to points where the selected displacement ceases to be monotonic.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["It can follow a descending load branch using prescribed motion.","It does not require solving equilibrium.","It is the only way to model dynamic impacts.","It removes all possible turning points."],"correct":0},{"id":"c063","topic":"03_Path_following","question":"What is the basic idea of an arc-length method?","answer":"Solve for both displacement increments and load increment under an additional constraint on the step length.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Treat load and displacement increments as unknowns with a path constraint.","Hold all nodal displacements at zero.","Use constant time increments without equilibrium iterations.","Ignore the load multiplier and solve only eigenvalues."],"correct":0},{"id":"c064","topic":"03_Path_following","question":"Why does arc-length control require one extra equation?","answer":"Both ΔD and Δλ are unknown; equilibrium alone supplies one fewer independent equation.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["It provides the extra relation needed to solve for load and DOFs together.","It removes the need for the equilibrium equations.","It guarantees the structure is stable.","It replaces the constitutive relation."],"correct":0},{"id":"c065","topic":"03_Path_following","question":"Give a typical spherical arc-length constraint.","answer":"\\(\\Delta\\mathbf D^T\\Delta\\mathbf D+\\psi^2\\Delta\\lambda^2\\mathbf P_{ref}^T\\mathbf P_{ref}=\\Delta s^2\\).","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["\\(\\Delta\\mathbf D^T\\Delta\\mathbf D+\\psi^2\\Delta\\lambda^2\\mathbf P_{ref}^T\\mathbf P_{ref}=\\Delta s^2\\).","Solve for both displacement increments and load increment under an additional constraint on the step length.","Neither load nor a single displacement is the sole path parameter.","The path reverses in load, so load cannot serve as a unique monotonically increasing control parameter."],"correct":0},{"id":"c066","topic":"03_Path_following","question":"What is the role of the arc-length radius Δs?","answer":"It sets the distance advanced along the combined displacement-load path.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["It sets the distance advanced along the combined displacement-load path.","Neither load nor a single displacement is the sole path parameter.","A point at which the load parameter has a local extremum along the path (dλ/ds = 0).","Solve for both displacement increments and load increment under an additional constraint on the step length."],"correct":0},{"id":"c067","topic":"03_Path_following","question":"Why can arc-length methods traverse limit and turning points?","answer":"Neither load nor a single displacement is the sole path parameter.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["It controls the combined load–displacement path length, not one axis alone.","It assumes the tangent stiffness never becomes singular.","It uses a lumped mass matrix at every increment.","It requires linear material behavior with zero rotation."],"correct":0},{"id":"c068","topic":"03_Path_following","question":"What is the Modified Riks method used for in Abaqus?","answer":"Tracing nonlinear equilibrium paths through unstable snap-through or postbuckling segments.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Tracing unstable equilibrium paths, including snap-through.","Calculating undamped natural frequencies only.","Computing explicit contact trajectories only.","Assigning rigid MPC constraints to beam elements."],"correct":0},{"id":"c069","topic":"03_Path_following","question":"What does an equilibrium-path tangent contain?","answer":"Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\).","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\).","A point at which the load parameter has a local extremum along the path (dλ/ds = 0).","\\(\\mathbf K_t\\,d\\mathbf D-\\mathbf P_{ref}\\,d\\lambda=\\mathbf 0\\).","\\(d\\lambda/ds=0\\); the tangent points purely in displacement space."],"correct":0},{"id":"c070","topic":"03_Path_following","question":"What is the path-tangent equation for dead loads?","answer":"\\(\\mathbf K_t\\,d\\mathbf D-\\mathbf P_{ref}\\,d\\lambda=\\mathbf 0\\).","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["\\(\\mathbf K_t\\,d\\mathbf D-\\mathbf P_{ref}\\,d\\lambda=\\mathbf 0\\).","Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\).","\\(\\det\\mathbf K_t=0\\), or equivalently at least one zero eigenvalue of tangent stiffness.","No. Both limit points and bifurcations can have a singular tangent."],"correct":0},{"id":"c071","topic":"03_Path_following","question":"What happens to dλ/ds at a simple load limit point?","answer":"\\(d\\lambda/ds=0\\); the tangent points purely in displacement space.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["\\(d\\lambda/ds=0\\); the tangent points purely in displacement space.","A point at which the load parameter has a local extremum along the path (dλ/ds = 0).","No. Both limit points and bifurcations can have a singular tangent.","Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\)."],"correct":0},{"id":"c072","topic":"03_Path_following","question":"How does a bifurcation differ physically from a limit point?","answer":"At a bifurcation a new deformation mode/branch becomes available; at a limit point the existing branch folds.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Bifurcation branches; a simple limit point is one branch with a load extremum.","Bifurcation is always plastic; a limit point is always elastic.","Bifurcation requires nonconservative loads only.","A limit point occurs only during explicit dynamics."],"correct":0},{"id":"c073","topic":"03_Path_following","question":"What is a fundamental versus secondary branch after buckling?","answer":"Fundamental: pre-existing symmetric solution; secondary: buckled or symmetry-breaking solution emerging at bifurcation.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Fundamental: pre-existing symmetric solution; secondary: buckled or symmetry-breaking solution emerging at bifurcation.","Reaction force versus imposed displacement gives the load–deflection curve, including descending-load segments.","The path reverses in load, so load cannot serve as a unique monotonically increasing control parameter.","Path curvature, stiffness changes, desired accuracy, iteration count, and proximity to critical points."],"correct":0},{"id":"c074","topic":"03_Path_following","question":"Why might an imperfect structure not show a perfect bifurcation?","answer":"Initial geometric/material imperfections can unfold the ideal branching into a smooth but strongly nonlinear response.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Initial geometric/material imperfections can unfold the ideal branching into a smooth but strongly nonlinear response.","Evaluate stability/energy, imperfections, and loading control—not simply the branch with the largest displacement.","Path curvature, stiffness changes, desired accuracy, iteration count, and proximity to critical points.","It can follow load-dropping (snap-through) response up to points where the selected displacement ceases to be monotonic."],"correct":0},{"id":"c075","topic":"03_Path_following","question":"What determines an appropriate load increment size?","answer":"Path curvature, stiffness changes, desired accuracy, iteration count, and proximity to critical points.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Path curvature, stiffness changes, desired accuracy, iteration count, and proximity to critical points.","Increase step size when convergence is easy and reduce it when many iterations or cutbacks are needed.","Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\).","\\(\\Delta\\mathbf D^T\\Delta\\mathbf D+\\psi^2\\Delta\\lambda^2\\mathbf P_{ref}^T\\mathbf P_{ref}=\\Delta s^2\\)."],"correct":0},{"id":"c076","topic":"03_Path_following","question":"How can automatic increment control use iteration count?","answer":"Increase step size when convergence is easy and reduce it when many iterations or cutbacks are needed.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Increase step size when convergence is easy and reduce it when many iterations or cutbacks are needed.","Path curvature, stiffness changes, desired accuracy, iteration count, and proximity to critical points.","The chosen displacement reverses, so the response cannot be uniquely advanced by prescribing that DOF.","It can follow load-dropping (snap-through) response up to points where the selected displacement ceases to be monotonic."],"correct":0},{"id":"c077","topic":"03_Path_following","question":"Why is an initial large increment dangerous near snap-through?","answer":"The predictor may jump across a critical region or converge to an unintended branch.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["The predictor may jump across a critical region or converge to an unintended branch.","\\(\\det\\mathbf K_t=0\\), or equivalently at least one zero eigenvalue of tangent stiffness.","Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\).","A point at which the load parameter has a local extremum along the path (dλ/ds = 0)."],"correct":0},{"id":"c078","topic":"03_Path_following","question":"How do you decide which branch is physically stable after a bifurcation?","answer":"Evaluate stability/energy, imperfections, and loading control—not simply the branch with the largest displacement.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Evaluate stability/energy, imperfections, and loading control—not simply the branch with the largest displacement.","At a bifurcation a new deformation mode/branch becomes available; at a limit point the existing branch folds.","The path reverses in load, so load cannot serve as a unique monotonically increasing control parameter.","Reaction force versus imposed displacement gives the load–deflection curve, including descending-load segments."],"correct":0},{"id":"c079","topic":"03_Path_following","question":"Why is automatic time incrementation not equivalent to physical time in static analysis?","answer":"The increment advances a normalized loading parameter, not necessarily actual seconds.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["The increment advances a normalized loading parameter, not necessarily actual seconds.","\\(\\det\\mathbf K_t=0\\), or equivalently at least one zero eigenvalue of tangent stiffness.","Both ΔD and Δλ are unknown; equilibrium alone supplies one fewer independent equation.","Both \\(d\\mathbf D/ds\\) and \\(d\\lambda/ds\\), normalized together for a selected path parameter \\(s\\)."],"correct":0},{"id":"c080","topic":"03_Path_following","question":"How does the reaction at a prescribed displacement help trace response?","answer":"Reaction force versus imposed displacement gives the load–deflection curve, including descending-load segments.","source":"Lecture 3; Lecture 14; Exercise 2; Exercise 12; Exam 2021 P1-P2; Exam 2022 P1; Exam 2025 P1","options":["Reaction force versus imposed displacement gives the load–deflection curve, including descending-load segments.","Solve for both displacement increments and load increment under an additional constraint on the step length.","The chosen displacement reverses, so the response cannot be uniquely advanced by prescribing that DOF.","At a bifurcation a new deformation mode/branch becomes available; at a limit point the existing branch folds."],"correct":0},{"id":"c081","topic":"04_Plasticity","question":"What distinguishes elastic from plastic strain?","answer":"Elastic strain is recoverable upon unloading; plastic strain is permanent and history-dependent.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Elastic strain recovers on unloading; plastic strain remains.","Plastic strain always recovers but elastic strain is permanent.","Both strains are always completely recovered.","Both strains depend only on time integration accuracy."],"correct":0},{"id":"c082","topic":"04_Plasticity","question":"State the additive small-strain decomposition in plasticity.","answer":"\\(d\\boldsymbol\\varepsilon=d\\boldsymbol\\varepsilon^e+d\\boldsymbol\\varepsilon^p\\).","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["dε = dεᵉ + dεᵖ.","dε = dσ + dλ.","dε = dεᵉ × dεᵖ.","dε = dεᵉ − dεᵖ only."],"correct":0},{"id":"c083","topic":"04_Plasticity","question":"How are incremental stresses related to elastic strain increments?","answer":"\\(d\\boldsymbol\\sigma=\\mathbf C^e(d\\boldsymbol\\varepsilon-d\\boldsymbol\\varepsilon^p)\\).","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["\\(d\\boldsymbol\\sigma=\\mathbf C^e(d\\boldsymbol\\varepsilon-d\\boldsymbol\\varepsilon^p)\\).","Elastic strain is recoverable upon unloading; plastic strain is permanent and history-dependent.","First compute an elastic trial stress; if inadmissible, project/correct back to the yield surface.","An internal stress-like variable locating the center of the kinematic yield surface."],"correct":0},{"id":"c084","topic":"04_Plasticity","question":"What does a yield function F < 0 represent?","answer":"An admissible elastic stress state strictly inside the yield surface.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["The stress state is strictly inside the elastic domain.","The stress state is on the yield surface.","The stress state lies outside the admissible yield surface.","The yield function is a strain-rate measure."],"correct":0},{"id":"c085","topic":"04_Plasticity","question":"What does F = 0 represent?","answer":"A stress state on the yield surface: plastic loading or elastic unloading may occur.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["A stress state on the yield surface.","An inadmissible stress state outside the yield surface.","A fully unloaded structure with zero stress.","A vanishing elastic modulus in every direction."],"correct":0},{"id":"c086","topic":"04_Plasticity","question":"What does F > 0 indicate?","answer":"An inadmissible trial stress state that must be corrected by a return mapping.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["An inadmissible trial state requiring plastic correction.","An admissible elastic state inside the yield surface.","An equilibrium state with zero residual.","A stationary total potential energy."],"correct":0},{"id":"c087","topic":"04_Plasticity","question":"What does isotropic hardening do to a yield surface?","answer":"Expands (or contracts) its size without translating its center.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["It expands the yield surface without translating its center.","It translates the yield surface without changing size.","It rotates the elastic stiffness matrix only.","It eliminates the Bauschinger effect by setting E to zero."],"correct":0},{"id":"c088","topic":"04_Plasticity","question":"What does kinematic hardening do to a yield surface?","answer":"Translates its center in stress space, represented by a backstress.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["It translates the yield surface in stress space.","It expands the yield surface uniformly without translation.","It changes only the mass density during loading.","It sets the plastic strain increment to zero."],"correct":0},{"id":"c089","topic":"04_Plasticity","question":"Which hardening type models the Bauschinger effect?","answer":"Kinematic hardening, because reverse yielding begins at a shifted effective stress.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Kinematic hardening.","Isotropic hardening only.","Elastic-perfectly plastic response with no backstress.","Rayleigh proportional damping."],"correct":0},{"id":"c090","topic":"04_Plasticity","question":"What is backstress α?","answer":"An internal stress-like variable locating the center of the kinematic yield surface.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["A stress-like internal variable locating the yield-surface center.","The elastic shear modulus of the material.","A geometric displacement constraint.","The residual force norm at convergence."],"correct":0},{"id":"c091","topic":"04_Plasticity","question":"Give the combined-hardening uniaxial yield function.","answer":"\\(F=|\\sigma-\\alpha|-(\\sigma_{y0}+K\\gamma)\\leq0\\).","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["\\(F=|\\sigma-\\alpha|-(\\sigma_{y0}+K\\gamma)\\leq0\\).","An admissible elastic stress state strictly inside the yield surface.","Translates its center in stress space, represented by a backstress.","Expands (or contracts) its size without translating its center."],"correct":0},{"id":"c092","topic":"04_Plasticity","question":"What does γ describe in a uniaxial hardening model?","answer":"Accumulated plastic multiplier/absolute plastic deformation controlling isotropic hardening.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["A scalar measuring accumulated plastic flow/hardening history.","The geometric curvature of a truss element.","The cyclic loading frequency in hertz.","The tangent stiffness eigenvalue."],"correct":0},{"id":"c093","topic":"04_Plasticity","question":"What is the meaning of the plastic multiplier?","answer":"Its nonnegative increment scales the irreversible plastic flow increment.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["The scalar multiplier controlling the amount of plastic flow.","A finite-element mode-shape amplitude.","The ratio of mass scaling to stable time step.","The increment in prescribed contact gap."],"correct":0},{"id":"c094","topic":"04_Plasticity","question":"State the associated plastic flow rule.","answer":"\\(d\\boldsymbol\\varepsilon^p=d\\lambda\\,\\partial F/\\partial\\boldsymbol\\sigma\\).","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["\\(d\\boldsymbol\\varepsilon^p=d\\lambda\\,\\partial F/\\partial\\boldsymbol\\sigma\\).","\\(d\\boldsymbol\\varepsilon=d\\boldsymbol\\varepsilon^e+d\\boldsymbol\\varepsilon^p\\).","Its plastic potential Q differs from the yield function F.","After yielding, additional deformation occurs without isotropic uniaxial stress hardening."],"correct":0},{"id":"c095","topic":"04_Plasticity","question":"What makes a flow rule nonassociated?","answer":"Its plastic potential Q differs from the yield function F.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["The plastic potential differs from the yield function.","The plastic potential is identical to the yield function.","The yield surface must have radius zero.","The material does not develop plastic strains."],"correct":0},{"id":"c096","topic":"04_Plasticity","question":"State the plastic consistency condition during plastic loading.","answer":"\\(F=0\\) and \\(dF=0\\) while \\(d\\lambda>0\\).","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["During plastic loading, the updated stress stays on F = 0 (dF = 0).","The yield function must grow without bound.","The elastic modulus becomes zero.","The plastic multiplier remains negative."],"correct":0},{"id":"c097","topic":"04_Plasticity","question":"What are the Kuhn–Tucker conditions for rate-independent plasticity?","answer":"\\(F\\le0,\\ d\\lambda\\ge0,\\ d\\lambda F=0\\); with consistency while plastic flow occurs.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["\\(F\\le0,\\ d\\lambda\\ge0,\\ d\\lambda F=0\\); with consistency while plastic flow occurs.","Its nonnegative increment scales the irreversible plastic flow increment.","Accumulated plastic multiplier/absolute plastic deformation controlling isotropic hardening.","After yielding, additional deformation occurs without isotropic uniaxial stress hardening."],"correct":0},{"id":"c098","topic":"04_Plasticity","question":"What is elastic predictor–plastic corrector return mapping?","answer":"First compute an elastic trial stress; if inadmissible, project/correct back to the yield surface.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Make an elastic trial, check yield, then return plastic stress to the surface.","Assume all stress increments are always elastic.","Update the global mass matrix before applying load.","Set stress to zero when yielding begins."],"correct":0},{"id":"c099","topic":"04_Plasticity","question":"Why is return mapping needed in a finite strain increment?","answer":"An elastic stress trial can violate the yield constraint even if the prior state was admissible.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["An elastic stress trial can violate the yield constraint even if the prior state was admissible.","First compute an elastic trial stress; if inadmissible, project/correct back to the yield surface.","An admissible elastic stress state strictly inside the yield surface.","Shifted reverse-yield points and hysteresis loops due to translated yield surfaces."],"correct":0},{"id":"c100","topic":"04_Plasticity","question":"What is an algorithmic consistent tangent in plasticity?","answer":"The derivative of the discrete return-mapping stress update with respect to the total strain increment.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["The derivative of the discrete stress-update algorithm.","The initial elastic modulus only, independent of state.","The secant slope between initial and final load.","The explicit critical time increment."],"correct":0},{"id":"c101","topic":"04_Plasticity","question":"Why does elastic–perfectly plastic behavior reduce structural tangent stiffness?","answer":"After yielding, additional deformation occurs without isotropic uniaxial stress hardening.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["After yielding, additional deformation occurs without isotropic uniaxial stress hardening.","Accumulated plastic multiplier/absolute plastic deformation controlling isotropic hardening.","Kinematic hardening, because reverse yielding begins at a shifted effective stress.","Elastic strain is recoverable upon unloading; plastic strain is permanent and history-dependent."],"correct":0},{"id":"c102","topic":"04_Plasticity","question":"What is a typical feature of a cyclic stress–strain curve with kinematic hardening?","answer":"Shifted reverse-yield points and hysteresis loops due to translated yield surfaces.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Shifted reverse-yield points and hysteresis loops due to translated yield surfaces.","Kinematic hardening, because reverse yielding begins at a shifted effective stress.","A stress state on the yield surface: plastic loading or elastic unloading may occur.","An elastic stress trial can violate the yield constraint even if the prior state was admissible."],"correct":0},{"id":"c103","topic":"04_Plasticity","question":"Why does plastic dissipation make unloading different from loading?","answer":"Unloading generally follows an elastic slope; residual plastic strain remains.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Unloading generally follows an elastic slope; residual plastic strain remains.","Elastic strain is recoverable upon unloading; plastic strain is permanent and history-dependent.","A stress state on the yield surface: plastic loading or elastic unloading may occur.","Accumulated plastic multiplier/absolute plastic deformation controlling isotropic hardening."],"correct":0},{"id":"c104","topic":"04_Plasticity","question":"What is the difference between the elastic modulus and tangent modulus?","answer":"E is the elastic slope; the current tangent modulus is the incremental stress–strain slope after nonlinear effects.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["E is the elastic slope; the current tangent modulus is the incremental stress–strain slope after nonlinear effects.","Unloading generally follows an elastic slope; residual plastic strain remains.","Elastic strain is recoverable upon unloading; plastic strain is permanent and history-dependent.","First compute an elastic trial stress; if inadmissible, project/correct back to the yield surface."],"correct":0},{"id":"c105","topic":"04_Plasticity","question":"Why is through-thickness integration important for plastic beam bending?","answer":"Only parts of the cross-section may yield, so stress resultants depend on stress variation across thickness.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Only parts of the cross-section may yield, so stress resultants depend on stress variation across thickness.","Its integration points lie inside the section, whereas Lobatto integration can include the outer surfaces.","An elastic stress trial can violate the yield constraint even if the prior state was admissible.","After yielding, additional deformation occurs without isotropic uniaxial stress hardening."],"correct":0},{"id":"c106","topic":"04_Plasticity","question":"Why can Gauss integration miss a plastification front at a beam surface?","answer":"Its integration points lie inside the section, whereas Lobatto integration can include the outer surfaces.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Its integration points lie inside the section, whereas Lobatto integration can include the outer surfaces.","Only parts of the cross-section may yield, so stress resultants depend on stress variation across thickness.","Elastic strain is recoverable upon unloading; plastic strain is permanent and history-dependent.","Expands (or contracts) its size without translating its center."],"correct":0},{"id":"c107","topic":"04_Plasticity","question":"What is the disadvantage of too few section integration points?","answer":"Poor resolution of the evolving yielded region, moments, and stiffness.","source":"Lecture 5; Lecture 14; Exercise 4; Exercise 5","options":["Poor resolution of the evolving yielded region, moments, and stiffness.","An admissible elastic stress state strictly inside the yield surface.","Unloading generally follows an elastic slope; residual plastic strain remains.","Its nonnegative increment scales the irreversible plastic flow increment."],"correct":0},{"id":"c108","topic":"05_Structural_dynamics_and_mass","question":"State the linear FE equation of motion.","answer":"\\(\\mathbf M\\ddot{\\mathbf D}+\\mathbf C\\dot{\\mathbf D}+\\mathbf K\\mathbf D=\\mathbf R(t)\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["M D¨ + C D˙ + K D = R(t).","K_t ΔD = R_ext − R_int only.","K_m + λ K_g = 0.","FᵀF = I + 2E."],"correct":0},{"id":"c109","topic":"05_Structural_dynamics_and_mass","question":"What three physical forces appear in structural dynamics?","answer":"Inertia, damping, and elastic/internal restoring forces.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["Inertia, damping, and elastic/internal restoring forces.","A mode shape: relative motion of the DOFs at a particular natural frequency.","Inertia and wave propagation influence the response and cannot be neglected.","A diagonal representation that assigns masses directly to nodal DOFs."],"correct":0},{"id":"c110","topic":"05_Structural_dynamics_and_mass","question":"When can cyclic loading often be approximated as quasi-static?","answer":"When its frequency is well below the fundamental natural frequency (lecture guideline: below ~¼).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["When loading frequency is well below the fundamental frequency.","Whenever loading frequency equals a natural frequency.","Whenever the structure has geometric nonlinearity.","Only when the consistent mass matrix is singular."],"correct":0},{"id":"c111","topic":"05_Structural_dynamics_and_mass","question":"Why must a rapid impact generally be analyzed dynamically?","answer":"Inertia and wave propagation influence the response and cannot be neglected.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["Inertia and wave propagation influence the response and cannot be neglected.","\\(\\mathbf M_c=\\frac{\\rho AL}{6}\\begin{bmatrix}2&1\\\\1&2\\end{bmatrix}\\).","Inertia, damping, and elastic/internal restoring forces.","\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation."],"correct":0},{"id":"c112","topic":"05_Structural_dynamics_and_mass","question":"Give the natural frequency of an undamped SDOF spring–mass system.","answer":"\\(\\omega_n=\\sqrt{k/m}\\), with \\(f_n=\\omega_n/(2\\pi)\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["ω = √(k/m).","ω = √(m/k).","ω = 2π√(m/k).","ω = k/m."],"correct":0},{"id":"c113","topic":"05_Structural_dynamics_and_mass","question":"State the undamped free-vibration eigenvalue problem.","answer":"\\((\\mathbf K-\\omega^2\\mathbf M)\\boldsymbol\\phi=\\mathbf0\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["(K − ω²M) φ = 0.","(K + ω²M) φ = R_ext.","(M − ωK) φ = 0.","K_t ΔD = R_res."],"correct":0},{"id":"c114","topic":"05_Structural_dynamics_and_mass","question":"What does an eigenvector φ represent in structural dynamics?","answer":"A mode shape: relative motion of the DOFs at a particular natural frequency.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["A mode shape: relative motion of the DOFs at a particular natural frequency.","Amplified dynamic response when the excitation frequency is close to a natural frequency.","Inertia, damping, and elastic/internal restoring forces.","When its frequency is well below the fundamental natural frequency (lecture guideline: below ~¼)."],"correct":0},{"id":"c115","topic":"05_Structural_dynamics_and_mass","question":"What is resonance?","answer":"Amplified dynamic response when the excitation frequency is close to a natural frequency.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["Large response when excitation is near a natural frequency.","A sudden reduction of all mass entries to zero.","A stable load limit point in static equilibrium.","A change from isotropic to kinematic hardening."],"correct":0},{"id":"c116","topic":"05_Structural_dynamics_and_mass","question":"Why is modal superposition usually harder for nonlinear problems?","answer":"The modes and superposition principle are generally no longer fixed/valid as the state changes.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["The modes and superposition principle are generally no longer fixed/valid as the state changes.","\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation.","They distribute mass and interpolation differently; rotational velocity fields reveal differences in accuracy.","A diagonal representation that assigns masses directly to nodal DOFs."],"correct":0},{"id":"c117","topic":"05_Structural_dynamics_and_mass","question":"What is the consistent mass matrix?","answer":"\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["Mass obtained using the element shape functions in an integral.","All mass assigned exclusively to the fixed support.","The inverse stiffness matrix scaled by density.","A mass matrix formed from contact penalty factors."],"correct":0},{"id":"c118","topic":"05_Structural_dynamics_and_mass","question":"What is a lumped mass matrix?","answer":"A diagonal representation that assigns masses directly to nodal DOFs.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["Mass concentrated at nodal DOFs, often yielding a diagonal matrix.","A matrix assembled only from exact vibration modes.","A mass matrix that always contains large off-diagonal terms.","A matrix containing only damping coefficients."],"correct":0},{"id":"c119","topic":"05_Structural_dynamics_and_mass","question":"Write the 2-node bar consistent mass matrix.","answer":"\\(\\mathbf M_c=\\frac{\\rho AL}{6}\\begin{bmatrix}2&1\\\\1&2\\end{bmatrix}\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["\\(\\mathbf M_c=\\frac{\\rho AL}{6}\\begin{bmatrix}2&1\\\\1&2\\end{bmatrix}\\).","A diagonal representation that assigns masses directly to nodal DOFs.","It defines the slowest important structural oscillation timescale.","Inertia and wave propagation influence the response and cannot be neglected."],"correct":0},{"id":"c120","topic":"05_Structural_dynamics_and_mass","question":"Write the 2-node bar lumped mass matrix.","answer":"\\(\\mathbf M_l=\\frac{\\rho AL}{2}\\begin{bmatrix}1&0\\\\0&1\\end{bmatrix}\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["\\(\\mathbf M_l=\\frac{\\rho AL}{2}\\begin{bmatrix}1&0\\\\0&1\\end{bmatrix}\\).","\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation.","A diagonal M permits nodal acceleration calculations without solving coupled equations.","\\(T=\\frac12\\dot{\\mathbf D}^T\\mathbf M\\dot{\\mathbf D}\\)."],"correct":0},{"id":"c121","topic":"05_Structural_dynamics_and_mass","question":"Why is lumped mass especially useful with explicit time integration?","answer":"A diagonal M permits nodal acceleration calculations without solving coupled equations.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["Diagonal mass allows direct nodal acceleration updates without matrix solves.","It makes the explicit method unconditionally stable.","It removes physical inertia from the simulation.","It guarantees exact high-frequency wave propagation."],"correct":0},{"id":"c122","topic":"05_Structural_dynamics_and_mass","question":"Why is consistent mass often preferred for implicit dynamics?","answer":"It often represents natural frequencies and distributed inertia more accurately without losing the major implicit computational advantage.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["It often represents natural frequencies and distributed inertia more accurately without losing the major implicit computational advantage.","They distribute mass and interpolation differently; rotational velocity fields reveal differences in accuracy.","\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation.","\\(\\mathbf M_c=\\frac{\\rho AL}{6}\\begin{bmatrix}2&1\\\\1&2\\end{bmatrix}\\)."],"correct":0},{"id":"c123","topic":"05_Structural_dynamics_and_mass","question":"What is kinetic energy in a FE model?","answer":"\\(T=\\frac12\\dot{\\mathbf D}^T\\mathbf M\\dot{\\mathbf D}\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["\\(T=\\frac12\\dot{\\mathbf D}^T\\mathbf M\\dot{\\mathbf D}\\).","\\(\\mathbf C=\\alpha_M\\mathbf M+\\beta_K\\mathbf K\\).","\\((\\mathbf K-\\omega^2\\mathbf M)\\boldsymbol\\phi=\\mathbf0\\).","\\(c=\\sqrt{E/\\rho}\\), for the 1D axial bar model."],"correct":0},{"id":"c124","topic":"05_Structural_dynamics_and_mass","question":"Why can lumped and consistent mass give different rotational kinetic energies?","answer":"They distribute mass and interpolation differently; rotational velocity fields reveal differences in accuracy.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["They distribute mass and interpolation differently; rotational velocity fields reveal differences in accuracy.","\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation.","A diagonal M permits nodal acceleration calculations without solving coupled equations.","Amplified dynamic response when the excitation frequency is close to a natural frequency."],"correct":0},{"id":"c125","topic":"05_Structural_dynamics_and_mass","question":"What is Rayleigh damping?","answer":"\\(\\mathbf C=\\alpha_M\\mathbf M+\\beta_K\\mathbf K\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["C = αM + βK.","C = K − ω²M.","C = M⁻¹K.","C = K_m + K_g."],"correct":0},{"id":"c126","topic":"05_Structural_dynamics_and_mass","question":"What happens to Rayleigh damping at high frequencies when stiffness damping dominates?","answer":"The damping ratio grows approximately linearly with modal frequency.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["The damping ratio grows approximately linearly with modal frequency.","\\(\\mathbf C=\\alpha_M\\mathbf M+\\beta_K\\mathbf K\\).","\\(\\zeta_i=\\alpha_M/(2\\omega_i)+\\beta_K\\omega_i/2\\).","Amplified dynamic response when the excitation frequency is close to a natural frequency."],"correct":0},{"id":"c127","topic":"05_Structural_dynamics_and_mass","question":"How is the modal damping ratio expressed for Rayleigh damping?","answer":"\\(\\zeta_i=\\alpha_M/(2\\omega_i)+\\beta_K\\omega_i/2\\).","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["\\(\\zeta_i=\\alpha_M/(2\\omega_i)+\\beta_K\\omega_i/2\\).","The damping ratio grows approximately linearly with modal frequency.","\\(T=\\frac12\\dot{\\mathbf D}^T\\mathbf M\\dot{\\mathbf D}\\).","\\(c=\\sqrt{E/\\rho}\\), for the 1D axial bar model."],"correct":0},{"id":"c128","topic":"05_Structural_dynamics_and_mass","question":"Why is the lowest natural period useful when selecting a dynamic analysis?","answer":"It defines the slowest important structural oscillation timescale.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["It defines the slowest important structural oscillation timescale.","A diagonal representation that assigns masses directly to nodal DOFs.","The damping ratio grows approximately linearly with modal frequency.","\\(\\mathbf M_l=\\frac{\\rho AL}{2}\\begin{bmatrix}1&0\\\\0&1\\end{bmatrix}\\)."],"correct":0},{"id":"c129","topic":"05_Structural_dynamics_and_mass","question":"What is a dynamic response spectrum concerned with?","answer":"The maximum response of oscillators with varying frequencies or periods under a specified excitation.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["The maximum response of oscillators with varying frequencies or periods under a specified excitation.","Amplified dynamic response when the excitation frequency is close to a natural frequency.","\\(\\mathbf M\\ddot{\\mathbf D}+\\mathbf C\\dot{\\mathbf D}+\\mathbf K\\mathbf D=\\mathbf R(t)\\).","It defines the slowest important structural oscillation timescale."],"correct":0},{"id":"c130","topic":"05_Structural_dynamics_and_mass","question":"What is the dilatational wave speed of a 1D linear elastic bar?","answer":"\\(c=\\sqrt{E/\\rho}\\), for the 1D axial bar model.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["c = √(E/ρ).","c = √(ρ/E).","c = Eρ.","c = E/ρ²."],"correct":0},{"id":"c131","topic":"05_Structural_dynamics_and_mass","question":"Why are both spatial and temporal discretization important for wave propagation?","answer":"An insufficient mesh or time step can introduce numerical dispersion and miss traveling stress waves.","source":"Lecture 6; Lecture 14; Exercise 6; Exercise 8; Exam 2023 P3; Exam 2025 P4","options":["An insufficient mesh or time step can introduce numerical dispersion and miss traveling stress waves.","The modes and superposition principle are generally no longer fixed/valid as the state changes.","\\(\\mathbf M_e=\\int_V\\rho\\mathbf N^T\\mathbf N\\,dV\\); it follows the element interpolation.","Amplified dynamic response when the excitation frequency is close to a natural frequency."],"correct":0},{"id":"c132","topic":"06_Explicit_integration","question":"What makes a time integration method explicit?","answer":"The next state can be computed from known previous states without solving a coupled system at the new time.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Next state is calculated from previously known quantities.","Next state requires solving coupled equilibrium equations.","It always requires a Newton–Raphson iteration.","It is necessarily unconditionally stable."],"correct":0},{"id":"c133","topic":"06_Explicit_integration","question":"What makes the central difference method conditionally stable?","answer":"Its discrete solution is stable only when the time increment is below a critical value.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Stability depends on staying below a critical Δt.","It is stable for any Δt regardless of stiffness.","It is unstable only if damping is exactly zero.","Only nonlinear material models impose a time-step limit."],"correct":0},{"id":"c134","topic":"06_Explicit_integration","question":"Write the undamped central-difference acceleration approximation.","answer":"\\(\\ddot u_n\\approx(u_{n+1}-2u_n+u_{n-1})/\\Delta t^2\\).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["aₙ ≈ (uₙ₊₁ − 2uₙ + uₙ₋₁)/Δt².","aₙ ≈ (uₙ₊₁ − uₙ)/Δt.","aₙ ≈ (uₙ + uₙ₋₁)/Δt².","aₙ ≈ (uₙ₊₁ + 2uₙ + uₙ₋₁)/Δt²."],"correct":0},{"id":"c135","topic":"06_Explicit_integration","question":"Write the conventional central difference displacement update for M u¨ + Rint = Rext.","answer":"\\(\\mathbf D_{n+1}=2\\mathbf D_n-\\mathbf D_{n-1}+\\Delta t^2\\mathbf M^{-1}(\\mathbf R_{ext,n}-\\mathbf R_{int,n})\\).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["\\(\\mathbf D_{n+1}=2\\mathbf D_n-\\mathbf D_{n-1}+\\Delta t^2\\mathbf M^{-1}(\\mathbf R_{ext,n}-\\mathbf R_{int,n})\\).","\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","Compute \\(\\ddot{\\mathbf D}_0\\) from equilibrium and use \\(\\mathbf D_{-1}=\\mathbf D_0-\\Delta t\\dot{\\mathbf D}_0+\\frac12\\Delta t^2\\ddot{\\mathbf D}_0\\).","It may diverge rapidly when Δt exceeds the critical increment despite perfectly correct initial conditions."],"correct":0},{"id":"c136","topic":"06_Explicit_integration","question":"What is the half-step central difference velocity update?","answer":"\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","\\(\\mathbf D_{n+1}=\\mathbf D_n+\\Delta t\\,\\dot{\\mathbf D}_{n+1/2}\\).","Compute \\(\\ddot{\\mathbf D}_0\\) from equilibrium and use \\(\\mathbf D_{-1}=\\mathbf D_0-\\Delta t\\dot{\\mathbf D}_0+\\frac12\\Delta t^2\\ddot{\\mathbf D}_0\\).","Its discrete solution is stable only when the time increment is below a critical value."],"correct":0},{"id":"c137","topic":"06_Explicit_integration","question":"How is displacement updated from half-step velocity?","answer":"\\(\\mathbf D_{n+1}=\\mathbf D_n+\\Delta t\\,\\dot{\\mathbf D}_{n+1/2}\\).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["\\(\\mathbf D_{n+1}=\\mathbf D_n+\\Delta t\\,\\dot{\\mathbf D}_{n+1/2}\\).","\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","\\(\\ddot u_n\\approx(u_{n+1}-2u_n+u_{n-1})/\\Delta t^2\\).","They can introduce high element frequencies and a smaller critical time step."],"correct":0},{"id":"c138","topic":"06_Explicit_integration","question":"What is the stable time increment for an undamped SDOF with central difference?","answer":"\\(\\Delta t_{cr}=2/\\omega_n\\) (without additional damping or corrections).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Δt ≤ 2/ω for an undamped linear SDOF.","Δt ≥ 2/ω for an undamped linear SDOF.","Δt ≤ ω/2.","Δt is unrestricted if mass is lumped."],"correct":0},{"id":"c139","topic":"06_Explicit_integration","question":"What is the MDOF central difference stability condition?","answer":"\\(\\Delta t\\le 2/\\omega_{max}\\) for an undamped linear system.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["\\(\\Delta t\\le 2/\\omega_{max}\\) for an undamped linear system.","\\(\\Delta t_{cr}=2/\\omega_n\\) (without additional damping or corrections).","\\(\\ddot u_n\\approx(u_{n+1}-2u_n+u_{n-1})/\\Delta t^2\\).","Second order in time for sufficiently smooth response with constant time steps."],"correct":0},{"id":"c140","topic":"06_Explicit_integration","question":"What physical timescale is the explicit critical increment related to?","answer":"The shortest time for an elastic stress wave to traverse the smallest controlling element.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["The period of the highest-frequency resolved mode.","The fundamental period only, regardless of the mesh.","The time required for plastic strain to reach one.","The rate of convergence of full Newton iterations."],"correct":0},{"id":"c141","topic":"06_Explicit_integration","question":"What approximate wave-transit rule is used for explicit Δt?","answer":"\\(\\Delta t_{cr}\\sim L_{min}/c\\), with a suitable characteristic element length and dilatational wave speed.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["\\(\\Delta t_{cr}\\sim L_{min}/c\\), with a suitable characteristic element length and dilatational wave speed.","\\(\\Delta t_{cr}=2/\\omega_n\\) (without additional damping or corrections).","The smallest, stiffest, or highest-wave-speed elements with the highest numerical frequencies.","The shortest time for an elastic stress wave to traverse the smallest controlling element."],"correct":0},{"id":"c142","topic":"06_Explicit_integration","question":"Which elements tend to control the explicit stable increment?","answer":"The smallest, stiffest, or highest-wave-speed elements with the highest numerical frequencies.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["The smallest/stiffest elements with highest local wave frequency.","Only the largest element in the model.","Elements with the lowest mass density regardless of stiffness.","Only elements where reaction forces are prescribed."],"correct":0},{"id":"c143","topic":"06_Explicit_integration","question":"Why do higher-order elements often become costly in explicit dynamics?","answer":"They can introduce high element frequencies and a smaller critical time step.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["They can introduce high element frequencies and a smaller critical time step.","Potentially enormous numbers of tiny time increments are needed.","Each increment is inexpensive and requires no nonlinear equilibrium iterations.","It makes M⁻¹ a trivial componentwise division; no global matrix factorization is required."],"correct":0},{"id":"c144","topic":"06_Explicit_integration","question":"Why is a diagonal mass matrix so important for explicit dynamics?","answer":"It makes M⁻¹ a trivial componentwise division; no global matrix factorization is required.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["It lets nodal accelerations be updated without a global linear solve.","It increases the stable time step to infinity.","It removes the need to calculate element forces.","It guarantees energy conservation during impact."],"correct":0},{"id":"c145","topic":"06_Explicit_integration","question":"How can lumped mass affect explicit stability?","answer":"It generally lowers the highest discrete frequencies and can permit a larger stable Δt.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["It generally lowers the highest discrete frequencies and can permit a larger stable Δt.","The smallest, stiffest, or highest-wave-speed elements with the highest numerical frequencies.","Damping can reduce the allowed stable Δt; it does not generally remove conditional stability.","It makes M⁻¹ a trivial componentwise division; no global matrix factorization is required."],"correct":0},{"id":"c146","topic":"06_Explicit_integration","question":"What is the accuracy order of the central difference method?","answer":"Second order in time for sufficiently smooth response with constant time steps.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Second order in time for a smooth solution.","First order in time, same as forward Euler.","Fourth order in time for all responses.","Zero order; it never converges with smaller Δt."],"correct":0},{"id":"c147","topic":"06_Explicit_integration","question":"What is the accuracy order of forward Euler time integration?","answer":"First order globally; local truncation error is O(Δt²).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["First order in time.","Second order in time.","Fourth order in time.","Unconditionally exact in time."],"correct":0},{"id":"c148","topic":"06_Explicit_integration","question":"What is the accuracy order of backward Euler time integration?","answer":"First order globally; local truncation error is O(Δt²).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["First order in time.","Second order in time.","Fourth order in time.","Exactly zero error for any Δt."],"correct":0},{"id":"c149","topic":"06_Explicit_integration","question":"Why is it inaccurate to call central difference unconditionally stable?","answer":"It may diverge rapidly when Δt exceeds the critical increment despite perfectly correct initial conditions.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["It may diverge rapidly when Δt exceeds the critical increment despite perfectly correct initial conditions.","\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","Its discrete solution is stable only when the time increment is below a critical value.","The stability bound limits blow-up, not time-integration error or mesh-induced dispersion."],"correct":0},{"id":"c150","topic":"06_Explicit_integration","question":"How can an explicit method be initialized from D₀ and V₀?","answer":"Compute \\(\\ddot{\\mathbf D}_0\\) from equilibrium and use \\(\\mathbf D_{-1}=\\mathbf D_0-\\Delta t\\dot{\\mathbf D}_0+\\frac12\\Delta t^2\\ddot{\\mathbf D}_0\\).","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Compute \\(\\ddot{\\mathbf D}_0\\) from equilibrium and use \\(\\mathbf D_{-1}=\\mathbf D_0-\\Delta t\\dot{\\mathbf D}_0+\\frac12\\Delta t^2\\ddot{\\mathbf D}_0\\).","\\(\\mathbf D_{n+1}=\\mathbf D_n+\\Delta t\\,\\dot{\\mathbf D}_{n+1/2}\\).","\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","It may diverge rapidly when Δt exceeds the critical increment despite perfectly correct initial conditions."],"correct":0},{"id":"c151","topic":"06_Explicit_integration","question":"What is the main computational advantage of explicit dynamics?","answer":"Each increment is inexpensive and requires no nonlinear equilibrium iterations.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["No global stiffness solve or equilibrium iteration each step.","Unconditionally stable, so arbitrarily large steps.","It always gives exact static equilibrium at every step.","It never needs to compute internal forces."],"correct":0},{"id":"c152","topic":"06_Explicit_integration","question":"What is the main computational drawback of explicit dynamics?","answer":"Potentially enormous numbers of tiny time increments are needed.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Very small stable time steps can require many increments.","It requires a full tangent factorization at every step.","It cannot model contact.","It is only accurate with consistent mass."],"correct":0},{"id":"c153","topic":"06_Explicit_integration","question":"Why is the Courant-like condition relevant to wave propagation?","answer":"The time step must resolve propagation between neighboring nodes; numerical signals must not skip elements.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["The time step must resolve propagation between neighboring nodes; numerical signals must not skip elements.","\\(\\Delta t_{cr}\\sim L_{min}/c\\), with a suitable characteristic element length and dilatational wave speed.","The smallest, stiffest, or highest-wave-speed elements with the highest numerical frequencies.","\\(\\mathbf D_{n+1}=2\\mathbf D_n-\\mathbf D_{n-1}+\\Delta t^2\\mathbf M^{-1}(\\mathbf R_{ext,n}-\\mathbf R_{int,n})\\)."],"correct":0},{"id":"c154","topic":"06_Explicit_integration","question":"How can accuracy be improved in an explicit simulation?","answer":"Refine both the mesh and time step, check wave resolution and energy balance, and compare results.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Refine both the mesh and time step, check wave resolution and energy balance, and compare results.","Second order in time for sufficiently smooth response with constant time steps.","They can introduce high element frequencies and a smaller critical time step.","\\(\\Delta t_{cr}\\sim L_{min}/c\\), with a suitable characteristic element length and dilatational wave speed."],"correct":0},{"id":"c155","topic":"06_Explicit_integration","question":"Why can an explicit run be stable but inaccurate?","answer":"The stability bound limits blow-up, not time-integration error or mesh-induced dispersion.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Stability alone does not ensure adequate time and space resolution.","Stability guarantees exact stress-wave arrival times.","Stability proves the mesh is converged.","Stability guarantees correct constitutive parameters."],"correct":0},{"id":"c156","topic":"06_Explicit_integration","question":"Why is stiffness-proportional damping awkward for central difference?","answer":"It couples velocities through a generally nondiagonal matrix, defeating cheap nodal explicit updates.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["It couples velocities through a generally nondiagonal matrix, defeating cheap nodal explicit updates.","It may diverge rapidly when Δt exceeds the critical increment despite perfectly correct initial conditions.","\\(\\dot{\\mathbf D}_{n+1/2}=\\dot{\\mathbf D}_{n-1/2}+\\Delta t\\,\\ddot{\\mathbf D}_n\\) for constant Δt.","Explicit steps are cheap but numerous; implicit steps are fewer but require matrix solutions and nonlinear iterations."],"correct":0},{"id":"c157","topic":"06_Explicit_integration","question":"How does damping change the explicit stable time increment?","answer":"Damping can reduce the allowed stable Δt; it does not generally remove conditional stability.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Damping can reduce the allowed stable Δt; it does not generally remove conditional stability.","It generally lowers the highest discrete frequencies and can permit a larger stable Δt.","\\(\\Delta t_{cr}=2/\\omega_n\\) (without additional damping or corrections).","The stability bound limits blow-up, not time-integration error or mesh-induced dispersion."],"correct":0},{"id":"c158","topic":"06_Explicit_integration","question":"Why is it important not to compare methods using only the number of time steps?","answer":"Explicit steps are cheap but numerous; implicit steps are fewer but require matrix solutions and nonlinear iterations.","source":"Lecture 14 (Lecture 7 summary); Lecture 9; Exercise 7; Exercise 9; Exam 2023 P3; Exam 2024 P4; Exam 2025 P4","options":["Explicit steps are cheap but numerous; implicit steps are fewer but require matrix solutions and nonlinear iterations.","It couples velocities through a generally nondiagonal matrix, defeating cheap nodal explicit updates.","The next state can be computed from known previous states without solving a coupled system at the new time.","Damping can reduce the allowed stable Δt; it does not generally remove conditional stability."],"correct":0},{"id":"c159","topic":"07_Implicit_integration","question":"What makes a time integration method implicit?","answer":"The state at time n+1 appears in its own governing equations, so an equilibrium solve is needed.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Unknown next-step quantities appear in equations requiring a solve.","All next-step values depend only on already-known values.","Only diagonal mass matrices are permitted.","No nonlinear equilibrium iterations are ever needed."],"correct":0},{"id":"c160","topic":"07_Implicit_integration","question":"What are the two Newmark integration parameters?","answer":"\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["β and γ.","E and ν.","α and ρ.","K and M."],"correct":0},{"id":"c161","topic":"07_Implicit_integration","question":"Write the Newmark velocity update.","answer":"\\(\\dot u_{n+1}=\\dot u_n+\\Delta t[(1-\\gamma)\\ddot u_n+\\gamma\\ddot u_{n+1}]\\).","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["\\(\\dot u_{n+1}=\\dot u_n+\\Delta t[(1-\\gamma)\\ddot u_n+\\gamma\\ddot u_{n+1}]\\).","\\(\\gamma=1/2,\\ \\beta=1/6\\).","\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course.","\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates."],"correct":0},{"id":"c162","topic":"07_Implicit_integration","question":"Write the Newmark displacement update.","answer":"\\(u_{n+1}=u_n+\\Delta t\\dot u_n+\\Delta t^2[(\\tfrac12-\\beta)\\ddot u_n+\\beta\\ddot u_{n+1}]\\).","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["\\(u_{n+1}=u_n+\\Delta t\\dot u_n+\\Delta t^2[(\\tfrac12-\\beta)\\ddot u_n+\\beta\\ddot u_{n+1}]\\).","\\(\\mathbf K_{eff}=\\mathbf K+\\frac{\\gamma}{\\beta\\Delta t}\\mathbf C+\\frac{1}{\\beta\\Delta t^2}\\mathbf M\\).","\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates.","Numerical damping is introduced, but the basic Newmark scheme generally drops to first-order accuracy."],"correct":0},{"id":"c163","topic":"07_Implicit_integration","question":"What Newmark parameters define the trapezoidal rule?","answer":"\\(\\gamma=1/2,\\ \\beta=1/4\\).","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["β = 1/4 and γ = 1/2.","β = 1/6 and γ = 1/2.","β = 0 and γ = 1.","β = 1/2 and γ = 1/4."],"correct":0},{"id":"c164","topic":"07_Implicit_integration","question":"What Newmark parameters define the linear acceleration method?","answer":"\\(\\gamma=1/2,\\ \\beta=1/6\\).","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["\\(\\gamma=1/2,\\ \\beta=1/6\\).","\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course.","\\(\\dot u_{n+1}=\\dot u_n+\\Delta t[(1-\\gamma)\\ddot u_n+\\gamma\\ddot u_{n+1}]\\).","\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates."],"correct":0},{"id":"c165","topic":"07_Implicit_integration","question":"Why is the trapezoidal rule important for linear undamped systems?","answer":"It is second-order, unconditionally stable, and conserves discrete total energy for constant-step linear problems.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["It is second-order and conserves energy for undamped linear systems.","It automatically removes all high-frequency modes.","It requires a diagonal stiffness matrix.","It is first-order and strongly dissipative at all frequencies."],"correct":0},{"id":"c166","topic":"07_Implicit_integration","question":"Is unconditional stability the same as unconditional accuracy?","answer":"No. A large Δt can suppress or distort important oscillations even if the calculation does not diverge.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["No. A stable method can still be inaccurate at large Δt.","Yes. Unconditionally stable always means exact.","Yes, if the mass matrix is diagonal.","No. Stability implies all modes are overdamped."],"correct":0},{"id":"c167","topic":"07_Implicit_integration","question":"What is the effective stiffness in Newmark for linear dynamics?","answer":"\\(\\mathbf K_{eff}=\\mathbf K+\\frac{\\gamma}{\\beta\\Delta t}\\mathbf C+\\frac{1}{\\beta\\Delta t^2}\\mathbf M\\).","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["\\(\\mathbf K_{eff}=\\mathbf K+\\frac{\\gamma}{\\beta\\Delta t}\\mathbf C+\\frac{1}{\\beta\\Delta t^2}\\mathbf M\\).","\\(\\gamma=1/2,\\ \\beta=1/4\\).","\\(u_{n+1}=u_n+\\Delta t\\dot u_n+\\Delta t^2[(\\tfrac12-\\beta)\\ddot u_n+\\beta\\ddot u_{n+1}]\\).","\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course."],"correct":0},{"id":"c168","topic":"07_Implicit_integration","question":"Why can an implicit dynamic problem be solvable even if K is singular?","answer":"The mass contribution in the effective stiffness can make the full effective matrix nonsingular.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["The mass contribution in the effective stiffness can make the full effective matrix nonsingular.","A coupled effective system is solved anyway, so mass lumping does not remove the main cost.","The state at time n+1 appears in its own governing equations, so an equilibrium solve is needed.","Smooth, long-duration response with moderate nonlinearities and no need to resolve very short waves."],"correct":0},{"id":"c169","topic":"07_Implicit_integration","question":"What is a sufficient unconditionally stable Newmark parameter relation for linear systems?","answer":"\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course.","\\(\\gamma=1/2,\\ \\beta=1/4\\).","\\(\\dot u_{n+1}=\\dot u_n+\\Delta t[(1-\\gamma)\\ddot u_n+\\gamma\\ddot u_{n+1}]\\).","\\(-1/3\\le\\alpha_H\\le0\\), \\(\\gamma=(1-2\\alpha_H)/2\\), \\(\\beta=(1-\\alpha_H)^2/4\\)."],"correct":0},{"id":"c170","topic":"07_Implicit_integration","question":"What happens if Newmark γ > 1/2?","answer":"Numerical damping is introduced, but the basic Newmark scheme generally drops to first-order accuracy.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Numerical damping is introduced, but the basic Newmark scheme generally drops to first-order accuracy.","HHT suppresses high-frequency noise while preserving second-order accuracy for its standard parameter choice.","It retains the Newmark kinematic relations but modifies the time weighting of internal, damping, and applied forces.","\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates."],"correct":0},{"id":"c171","topic":"07_Implicit_integration","question":"Why might numerical damping be desirable in structural dynamics?","answer":"It suppresses spurious high-frequency oscillations while retaining physically important lower modes.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["It suppresses spurious high-frequency oscillations while retaining physically important lower modes.","HHT suppresses high-frequency noise while preserving second-order accuracy for its standard parameter choice.","Exact conservation of undamped linear-system energy is lost; energy decreases due to algorithmic dissipation.","It removes numerical chatter without strongly damping the real lower-frequency structural response."],"correct":0},{"id":"c172","topic":"07_Implicit_integration","question":"What is the advantage of HHT-α over numerically damped Newmark?","answer":"HHT suppresses high-frequency noise while preserving second-order accuracy for its standard parameter choice.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["HHT suppresses high-frequency noise while preserving second-order accuracy for its standard parameter choice.","Numerical damping is introduced, but the basic Newmark scheme generally drops to first-order accuracy.","It suppresses spurious high-frequency oscillations while retaining physically important lower modes.","It is second-order, unconditionally stable, and conserves discrete total energy for constant-step linear problems."],"correct":0},{"id":"c173","topic":"07_Implicit_integration","question":"State the standard HHT-α stability parameter range.","answer":"\\(-1/3\\le\\alpha_H\\le0\\), \\(\\gamma=(1-2\\alpha_H)/2\\), \\(\\beta=(1-\\alpha_H)^2/4\\).","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["\\(-1/3\\le\\alpha_H\\le0\\), \\(\\gamma=(1-2\\alpha_H)/2\\), \\(\\beta=(1-\\alpha_H)^2/4\\).","\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course.","\\(\\gamma=1/2,\\ \\beta=1/4\\).","\\(\\mathbf K_{eff}=\\mathbf K+\\frac{\\gamma}{\\beta\\Delta t}\\mathbf C+\\frac{1}{\\beta\\Delta t^2}\\mathbf M\\)."],"correct":0},{"id":"c174","topic":"07_Implicit_integration","question":"How does making HHT α more negative change numerical damping?","answer":"It increases algorithmic dissipation, especially of higher-frequency modes.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["To suppress spurious high-frequency response while preserving lower modes.","To increase all natural frequencies uniformly.","To remove every physical damping mechanism.","To make nonlinear equations algebraically linear."],"correct":0},{"id":"c175","topic":"07_Implicit_integration","question":"What does HHT-α modify relative to Newmark?","answer":"It retains the Newmark kinematic relations but modifies the time weighting of internal, damping, and applied forces.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["It retains the Newmark kinematic relations but modifies the time weighting of internal, damping, and applied forces.","HHT suppresses high-frequency noise while preserving second-order accuracy for its standard parameter choice.","Numerical damping is introduced, but the basic Newmark scheme generally drops to first-order accuracy.","It is second-order, unconditionally stable, and conserves discrete total energy for constant-step linear problems."],"correct":0},{"id":"c176","topic":"07_Implicit_integration","question":"Why is selective high-frequency damping preferable to heavy physical damping?","answer":"It removes numerical chatter without strongly damping the real lower-frequency structural response.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["It removes numerical chatter without strongly damping the real lower-frequency structural response.","It suppresses spurious high-frequency oscillations while retaining physically important lower modes.","Numerical damping is introduced, but the basic Newmark scheme generally drops to first-order accuracy.","It increases algorithmic dissipation, especially of higher-frequency modes."],"correct":0},{"id":"c177","topic":"07_Implicit_integration","question":"What is period elongation error?","answer":"The computed oscillation period is longer than the exact period due to time-discretization error.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["The computed oscillation period is longer than the exact period due to time-discretization error.","Exact conservation of undamped linear-system energy is lost; energy decreases due to algorithmic dissipation.","It removes numerical chatter without strongly damping the real lower-frequency structural response.","The mass contribution in the effective stiffness can make the full effective matrix nonsingular."],"correct":0},{"id":"c178","topic":"07_Implicit_integration","question":"How should Δt be selected for unconditionally stable implicit integration?","answer":"Resolve the shortest relevant load/response period accurately; do not choose it based on stability alone.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Resolve the shortest relevant load/response period accurately; do not choose it based on stability alone.","\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates.","Smooth, long-duration response with moderate nonlinearities and no need to resolve very short waves.","\\(\\gamma\\ge1/2\\) and \\(\\beta\\ge\\gamma/2\\), as given in the course."],"correct":0},{"id":"c179","topic":"07_Implicit_integration","question":"Why can implicit time integration use a consistent mass matrix efficiently?","answer":"A coupled effective system is solved anyway, so mass lumping does not remove the main cost.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["A coupled effective system is solved anyway, so mass lumping does not remove the main cost.","The mass contribution in the effective stiffness can make the full effective matrix nonsingular.","\\(\\beta\\) and \\(\\gamma\\); they set how acceleration contributes to displacement and velocity updates.","The state at time n+1 appears in its own governing equations, so an equilibrium solve is needed."],"correct":0},{"id":"c180","topic":"07_Implicit_integration","question":"Can implicit dynamic analysis use variable time increments?","answer":"Yes for suitable algorithms, but abrupt changes may affect accuracy and some energy properties.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Yes for suitable algorithms, but abrupt changes may affect accuracy and some energy properties.","A coupled effective system is solved anyway, so mass lumping does not remove the main cost.","The mass contribution in the effective stiffness can make the full effective matrix nonsingular.","The state at time n+1 appears in its own governing equations, so an equilibrium solve is needed."],"correct":0},{"id":"c181","topic":"07_Implicit_integration","question":"When is implicit dynamics generally preferable to explicit dynamics?","answer":"Smooth, long-duration response with moderate nonlinearities and no need to resolve very short waves.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Smooth, long-duration response with moderate nonlinearities and no need to resolve very short waves.","Resolve the shortest relevant load/response period accurately; do not choose it based on stability alone.","\\(\\mathbf K_{eff}=\\mathbf K+\\frac{\\gamma}{\\beta\\Delta t}\\mathbf C+\\frac{1}{\\beta\\Delta t^2}\\mathbf M\\).","A coupled effective system is solved anyway, so mass lumping does not remove the main cost."],"correct":0},{"id":"c182","topic":"07_Implicit_integration","question":"What are key criteria for choosing a time integrator?","answer":"Stability, temporal accuracy, selective damping, computational cost, and support for variable Δt.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Stability, temporal accuracy, selective damping, computational cost, and support for variable Δt.","It removes numerical chatter without strongly damping the real lower-frequency structural response.","The state at time n+1 appears in its own governing equations, so an equilibrium solve is needed.","Yes for suitable algorithms, but abrupt changes may affect accuracy and some energy properties."],"correct":0},{"id":"c183","topic":"07_Implicit_integration","question":"What happens to trapezoidal-rule energy conservation when numerical damping is introduced?","answer":"Exact conservation of undamped linear-system energy is lost; energy decreases due to algorithmic dissipation.","source":"Lecture 8; Lecture 14; Exercise 8; Exercise 9; Exam 2022 P3","options":["Exact conservation of undamped linear-system energy is lost; energy decreases due to algorithmic dissipation.","It increases algorithmic dissipation, especially of higher-frequency modes.","It is second-order, unconditionally stable, and conserves discrete total energy for constant-step linear problems.","It suppresses spurious high-frequency oscillations while retaining physically important lower modes."],"correct":0},{"id":"c184","topic":"08_Nonlinear_dynamics_checks","question":"State the nonlinear FE dynamic equilibrium equation.","answer":"\\(\\mathbf M\\ddot{\\mathbf D}+\\mathbf R_{dmp}+\\mathbf R_{int}(\\mathbf D,\\mathbf q)=\\mathbf R_{ext}(t)\\).","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["M D¨ + R_dmp + R_int(D,q) = R_ext(t).","M D¨ + C D˙ − R_int = 0 always.","K_m + λK_g = 0.","R_int = −∂U/∂D regardless of constitutive law."],"correct":0},{"id":"c185","topic":"08_Nonlinear_dynamics_checks","question":"What do the internal variables q represent in nonlinear dynamics?","answer":"State/history quantities such as plastic strain, hardening, or damage.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["State/history quantities such as plastic strain, hardening, or damage.","Increasing selected element masses to raise the stable time step and shorten run time.","Repeated opening/closing creates artificial high-frequency oscillations and force spikes.","A plausible energy history alone may hide unrealistic local modes or incorrect contact."],"correct":0},{"id":"c186","topic":"08_Nonlinear_dynamics_checks","question":"Why is explicit dynamics well suited to complicated impact/contact?","answer":"Contact and material state updates can be handled without a global nonlinear equilibrium iteration.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["It handles many contact changes without global Newton iterations.","It is always more accurate regardless of time step.","It requires neither mass nor inertia.","It is unconditionally stable for arbitrarily large steps."],"correct":0},{"id":"c187","topic":"08_Nonlinear_dynamics_checks","question":"Why can an implicit increment fail to converge during impact?","answer":"The contact status and tangent stiffness may change abruptly, challenging the nonlinear solve.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["The contact status and tangent stiffness may change abruptly, challenging the nonlinear solve.","Contact and material state updates can be handled without a global nonlinear equilibrium iteration.","Nonphysical energy used to resist zero-energy deformation modes in underintegrated elements.","Repeated opening/closing creates artificial high-frequency oscillations and force spikes."],"correct":0},{"id":"c188","topic":"08_Nonlinear_dynamics_checks","question":"What is the basic explicit nonlinear dynamic update sequence?","answer":"Compute acceleration; update half-step velocity and displacement; enforce constraints; update stress/contact/internal forces.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Compute acceleration; update half-step velocity and displacement; enforce constraints; update stress/contact/internal forces.","Compare external work and initial energy with kinetic, internal, damping/contact dissipation, and artificial energies.","Repeated opening/closing creates artificial high-frequency oscillations and force spikes.","The contact status and tangent stiffness may change abruptly, challenging the nonlinear solve."],"correct":0},{"id":"c189","topic":"08_Nonlinear_dynamics_checks","question":"Why is a tangent stiffness matrix unnecessary in explicit dynamics?","answer":"Acceleration is obtained directly from the net force and diagonal mass instead of Newton iterations.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Acceleration is obtained directly from the net force and diagonal mass instead of Newton iterations.","Spatial wave resolution is still controlled by element size/interpolation and mass representation.","\\(\\mathbf M\\ddot{\\mathbf D}+\\mathbf R_{dmp}+\\mathbf R_{int}(\\mathbf D,\\mathbf q)=\\mathbf R_{ext}(t)\\).","Contact and material state updates can be handled without a global nonlinear equilibrium iteration."],"correct":0},{"id":"c190","topic":"08_Nonlinear_dynamics_checks","question":"What is artificial mass scaling in explicit FEA?","answer":"Increasing selected element masses to raise the stable time step and shorten run time.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Artificially increase selected masses to enlarge the explicit stable Δt.","Reduce all masses to approach a static solution.","Increase the Young modulus until convergence.","Replace every lumped mass with an identity matrix."],"correct":0},{"id":"c191","topic":"08_Nonlinear_dynamics_checks","question":"What is the physical risk of excessive mass scaling?","answer":"It changes inertia, wave speeds, natural frequencies, and possibly the predicted deformation and contact response.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["It alters inertia and may change deformation, forces, and impact response.","It always reduces dynamic effects without changing the physics.","It eliminates all artificial strain energy automatically.","It guarantees larger displacements at every node."],"correct":0},{"id":"c192","topic":"08_Nonlinear_dynamics_checks","question":"How can energy ratios help assess quasi-static explicit analysis?","answer":"Kinetic energy should remain small compared with meaningful internal energy during most of the process.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Check that kinetic energy stays small relative to internal energy.","Check that kinetic energy is always much larger than internal energy.","Check that elastic strain energy is exactly zero.","Check that contact pressure is independent of time step."],"correct":0},{"id":"c193","topic":"08_Nonlinear_dynamics_checks","question":"What is artificial strain energy or hourglass energy?","answer":"Nonphysical energy used to resist zero-energy deformation modes in underintegrated elements.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Nonphysical energy caused by numerical stabilization such as hourglass control.","Only the elastic strain energy stored in the material.","The load potential of a conservative static force.","The energy dissipated by exact plastic flow alone."],"correct":0},{"id":"c194","topic":"08_Nonlinear_dynamics_checks","question":"Why should artificial energy be monitored?","answer":"Large artificial energy indicates that numerical stabilization may significantly influence the result.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Large artificial energy indicates that numerical stabilization may significantly influence the result.","Nonphysical energy used to resist zero-energy deformation modes in underintegrated elements.","Kinetic energy should remain small compared with meaningful internal energy during most of the process.","Compare external work and initial energy with kinetic, internal, damping/contact dissipation, and artificial energies."],"correct":0},{"id":"c195","topic":"08_Nonlinear_dynamics_checks","question":"Why can numerical instability be hard to identify in nonlinear explicit models?","answer":"Real buckling, impact oscillations, and failure can resemble numerical instability.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Real buckling, impact oscillations, and failure can resemble numerical instability.","Increasing selected element masses to raise the stable time step and shorten run time.","Acceleration is obtained directly from the net force and diagonal mass instead of Newton iterations.","Kinetic energy should remain small compared with meaningful internal energy during most of the process."],"correct":0},{"id":"c196","topic":"08_Nonlinear_dynamics_checks","question":"What energy balance is useful in an explicit model?","answer":"Compare external work and initial energy with kinetic, internal, damping/contact dissipation, and artificial energies.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Compare external work and initial energy with kinetic, internal, damping/contact dissipation, and artificial energies.","Kinetic energy should remain small compared with meaningful internal energy during most of the process.","Large artificial energy indicates that numerical stabilization may significantly influence the result.","Compute acceleration; update half-step velocity and displacement; enforce constraints; update stress/contact/internal forces."],"correct":0},{"id":"c197","topic":"08_Nonlinear_dynamics_checks","question":"Why must the deformation animation be examined together with the energy history?","answer":"A plausible energy history alone may hide unrealistic local modes or incorrect contact.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["A plausible energy history alone may hide unrealistic local modes or incorrect contact.","Nonphysical energy used to resist zero-energy deformation modes in underintegrated elements.","Large artificial energy indicates that numerical stabilization may significantly influence the result.","State/history quantities such as plastic strain, hardening, or damage."],"correct":0},{"id":"c198","topic":"08_Nonlinear_dynamics_checks","question":"How can contact chatter contaminate a dynamic solution?","answer":"Repeated opening/closing creates artificial high-frequency oscillations and force spikes.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Repeated opening/closing creates artificial high-frequency oscillations and force spikes.","Real buckling, impact oscillations, and failure can resemble numerical instability.","\\(\\mathbf M\\ddot{\\mathbf D}+\\mathbf R_{dmp}+\\mathbf R_{int}(\\mathbf D,\\mathbf q)=\\mathbf R_{ext}(t)\\).","The contact status and tangent stiffness may change abruptly, challenging the nonlinear solve."],"correct":0},{"id":"c199","topic":"08_Nonlinear_dynamics_checks","question":"Why does a very small Δt not guarantee spatial accuracy?","answer":"Spatial wave resolution is still controlled by element size/interpolation and mass representation.","source":"Lecture 9; Lecture 14; Exercise 7; Exercise 8; Exercise 9; Exam 2023 P3","options":["Spatial wave resolution is still controlled by element size/interpolation and mass representation.","Acceleration is obtained directly from the net force and diagonal mass instead of Newton iterations.","The contact status and tangent stiffness may change abruptly, challenging the nonlinear solve.","It changes inertia, wave speeds, natural frequencies, and possibly the predicted deformation and contact response."],"correct":0},{"id":"c200","topic":"09_Constraints","question":"What is a kinematic constraint?","answer":"An equation prescribing a DOF or relating two or more DOFs.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["A condition that prescribes DOFs or relates multiple DOFs.","A criterion specifying where a material first yields.","A tensor transforming Cauchy to PK2 stresses.","The energy of a free vibration mode."],"correct":0},{"id":"c201","topic":"09_Constraints","question":"Name the three methods emphasized for imposing constraints.","answer":"Transformation (DOF elimination); Lagrange multipliers; penalty functions.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Transformation, Lagrange multipliers, and penalty methods.","Rayleigh damping, Newmark integration, and modal superposition.","Cauchy stress, Green strain, and deformation gradient.","Full Newton, modified Newton, and central difference only."],"correct":0},{"id":"c202","topic":"09_Constraints","question":"What is a single-point constraint?","answer":"A condition applied to one DOF, such as a fixed displacement or prescribed motion.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["A condition applied to one DOF, such as a fixed displacement or prescribed motion.","A relation among multiple DOFs, such as tying two displacements or enforcing rigid-body motion.","Its gradient changes with D, creating terms involving the Hessian of the constraint.","An equation prescribing a DOF or relating two or more DOFs."],"correct":0},{"id":"c203","topic":"09_Constraints","question":"What is a multi-point constraint?","answer":"A relation among multiple DOFs, such as tying two displacements or enforcing rigid-body motion.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["A relationship involving two or more DOFs.","A single prescribed nodal displacement only.","A boundary condition on material yield stress.","A force that always follows a rotating structure."],"correct":0},{"id":"c204","topic":"09_Constraints","question":"What distinguishes master and slave DOFs?","answer":"Master DOFs are retained as independent unknowns; slave DOFs are expressed in terms of them.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Master DOFs are retained; slave DOFs are expressed through them.","Master DOFs always have zero mass and slave DOFs have zero stiffness.","Slave DOFs remain independent while masters are eliminated.","Master and slave DOFs are always the same physical node."],"correct":0},{"id":"c205","topic":"09_Constraints","question":"How can a linear affine constraint be written?","answer":"\\(\\mathbf G\\mathbf D-\\mathbf Q=\\mathbf0\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["\\(\\mathbf G\\mathbf D-\\mathbf Q=\\mathbf0\\).","\\(\\Delta\\mathbf K=\\alpha\\mathbf G^T\\mathbf G\\).","\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\).","\\(\\Pi_\\alpha=\\Pi+\\frac{\\alpha}{2}\\mathbf C^T\\mathbf C\\), for positive penalty \\(\\alpha\\)."],"correct":0},{"id":"c206","topic":"09_Constraints","question":"How is a transformation of the original DOFs written?","answer":"\\(\\mathbf D=\\mathbf T\\mathbf D_m+\\mathbf D_0\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["\\(\\mathbf D=\\mathbf T\\mathbf D_m+\\mathbf D_0\\).","\\(\\Delta\\mathbf K=\\alpha\\mathbf G^T\\mathbf G\\).","\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\).","Extra unknowns and a larger indefinite coupled system."],"correct":0},{"id":"c207","topic":"09_Constraints","question":"What is the reduced stiffness under a DOF transformation?","answer":"\\(\\mathbf K_m=\\mathbf T^T\\mathbf K\\mathbf T\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["K* = Tᵀ K T.","K* = T K Tᵀ.","K* = T⁻¹ M T.","K* = K + αI for every constraint."],"correct":0},{"id":"c208","topic":"09_Constraints","question":"What is the reduced load for D = T Dm + D0?","answer":"\\(\\mathbf R_m=\\mathbf T^T(\\mathbf R-\\mathbf K\\mathbf D_0)\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["\\(\\mathbf R_m=\\mathbf T^T(\\mathbf R-\\mathbf K\\mathbf D_0)\\).","\\(\\Delta\\mathbf K=\\alpha\\mathbf G^T\\mathbf G\\).","\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\).","\\(\\Pi_\\alpha=\\Pi+\\frac{\\alpha}{2}\\mathbf C^T\\mathbf C\\), for positive penalty \\(\\alpha\\)."],"correct":0},{"id":"c209","topic":"09_Constraints","question":"Why is transformation efficient for linear constraints?","answer":"Dependent DOFs are eliminated, reducing system size without adding artificial stiffness.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["It eliminates dependent DOFs instead of adding unknown multipliers.","It increases the number of unknowns by one per constraint.","It always creates an indefinite saddle-point matrix.","It represents contact inequalities without any update."],"correct":0},{"id":"c210","topic":"09_Constraints","question":"What is a limitation of transformation for complicated nonlinear constraints?","answer":"Explicitly eliminating slave DOFs can become difficult when the constraint relation depends on the solution.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Explicitly eliminating slave DOFs can become difficult when the constraint relation depends on the solution.","Master DOFs are retained as independent unknowns; slave DOFs are expressed in terms of them.","The generalized constraint reaction, with sign and units depending on how the constraint is defined.","\\(\\sum_i\\lambda_i\\,\\nabla^2 C_i\\), in addition to material tangent and constraint-gradient blocks."],"correct":0},{"id":"c211","topic":"09_Constraints","question":"Write the Lagrange-multiplier augmented potential.","answer":"\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Π* = Π + λᵀC(D).","Π* = Π + (α/2) C(D)ᵀC(D).","Π* = Π + λ K_g.","Π* = Π − M D¨."],"correct":0},{"id":"c212","topic":"09_Constraints","question":"What extra unknown is added by the Lagrange multiplier method?","answer":"One reaction-like multiplier for each independent constraint equation.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["One multiplier per independent constraint equation.","One additional displacement per constrained element.","An extra lumped mass for every node.","No unknowns are added."],"correct":0},{"id":"c213","topic":"09_Constraints","question":"What is the physical interpretation of a Lagrange multiplier?","answer":"The generalized constraint reaction, with sign and units depending on how the constraint is defined.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["The generalized reaction force enforcing the constraint.","The load-control increment for the whole system.","The natural frequency of an unconstrained mode.","A change in initial material elasticity."],"correct":0},{"id":"c214","topic":"09_Constraints","question":"Write the linear Lagrange multiplier equilibrium system.","answer":"\\(\\begin{bmatrix}\\mathbf K&\\mathbf G^T\\\\\\mathbf G&0\\end{bmatrix}\\begin{Bmatrix}\\mathbf D\\\\\\boldsymbol\\lambda\\end{Bmatrix}=\\begin{Bmatrix}\\mathbf R\\\\\\mathbf Q\\end{Bmatrix}\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["\\(\\begin{bmatrix}\\mathbf K&\\mathbf G^T\\\\\\mathbf G&0\\end{bmatrix}\\begin{Bmatrix}\\mathbf D\\\\\\boldsymbol\\lambda\\end{Bmatrix}=\\begin{Bmatrix}\\mathbf R\\\\\\mathbf Q\\end{Bmatrix}\\).","\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\).","For \\(\\mathbf C=\\mathbf G\\mathbf D-\\mathbf Q\\), add \\(\\alpha\\mathbf G^T\\mathbf Q\\) to the load.","\\(\\sum_i\\lambda_i\\,\\nabla^2 C_i\\), in addition to material tangent and constraint-gradient blocks."],"correct":0},{"id":"c215","topic":"09_Constraints","question":"Why is the Lagrange multiplier matrix often indefinite?","answer":"The lower-right zero block gives the saddle-point system positive and negative directions.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["The lower-right zero block gives the saddle-point system positive and negative directions.","\\(\\sum_i\\lambda_i\\,\\nabla^2 C_i\\), in addition to material tangent and constraint-gradient blocks.","One reaction-like multiplier for each independent constraint equation.","Constraints are enforced exactly at convergence, without selecting a large penalty stiffness."],"correct":0},{"id":"c216","topic":"09_Constraints","question":"What is the main benefit of Lagrange multipliers?","answer":"Constraints are enforced exactly at convergence, without selecting a large penalty stiffness.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["The constraint is enforced exactly up to numerical tolerance.","The system stiffness always remains positive definite.","No additional unknown is introduced.","It is always better conditioned than transformation."],"correct":0},{"id":"c217","topic":"09_Constraints","question":"What is the main disadvantage of Lagrange multipliers?","answer":"Extra unknowns and a larger indefinite coupled system.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["It adds unknowns and can produce an indefinite augmented matrix.","It necessarily permits finite constraint violation.","It requires all constraints to be nonlinear.","It eliminates equilibrium equations entirely."],"correct":0},{"id":"c218","topic":"09_Constraints","question":"Write the penalty-method augmented potential for C = 0.","answer":"\\(\\Pi_\\alpha=\\Pi+\\frac{\\alpha}{2}\\mathbf C^T\\mathbf C\\), for positive penalty \\(\\alpha\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Π* = Π + (α/2)C(D)ᵀC(D).","Π* = Π + λᵀC(D).","Π* = Π − α C(D).","Π* = U + M D¨."],"correct":0},{"id":"c219","topic":"09_Constraints","question":"What is the main benefit of the penalty method?","answer":"No new multiplier DOFs; the constraint is enforced approximately through additional stiffness.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["It enforces constraints approximately without introducing multipliers.","It enforces constraints exactly for any finite penalty.","It always improves matrix conditioning as α increases.","It works only for free-vibration problems."],"correct":0},{"id":"c220","topic":"09_Constraints","question":"What is the main drawback of an excessively large penalty parameter?","answer":"Poor matrix conditioning and possibly slow or inaccurate numerical solutions.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["It can make the global system very ill-conditioned.","It guarantees exact solutions with no roundoff errors.","It eliminates the need to assemble stiffness.","It decreases the number of nonzero stiffness terms to zero."],"correct":0},{"id":"c221","topic":"09_Constraints","question":"What happens as the penalty parameter approaches infinity in theory?","answer":"Constraint violation tends to zero, but numerical conditioning deteriorates.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Constraint violation tends to zero in the ideal mathematical limit.","Constraint violation grows without bound.","The penalty approach becomes identical to consistent mass.","The system loses all unconstrained degrees of freedom."],"correct":0},{"id":"c222","topic":"09_Constraints","question":"How do you recognize the penalty stiffness contribution for a linear C = GD − Q?","answer":"\\(\\Delta\\mathbf K=\\alpha\\mathbf G^T\\mathbf G\\).","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["\\(\\Delta\\mathbf K=\\alpha\\mathbf G^T\\mathbf G\\).","\\(\\mathbf K_m=\\mathbf T^T\\mathbf K\\mathbf T\\).","\\(\\mathbf D=\\mathbf T\\mathbf D_m+\\mathbf D_0\\).","\\(\\Pi_\\alpha=\\Pi+\\frac{\\alpha}{2}\\mathbf C^T\\mathbf C\\), for positive penalty \\(\\alpha\\)."],"correct":0},{"id":"c223","topic":"09_Constraints","question":"How does a penalty affect the effective external load?","answer":"For \\(\\mathbf C=\\mathbf G\\mathbf D-\\mathbf Q\\), add \\(\\alpha\\mathbf G^T\\mathbf Q\\) to the load.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["For \\(\\mathbf C=\\mathbf G\\mathbf D-\\mathbf Q\\), add \\(\\alpha\\mathbf G^T\\mathbf Q\\) to the load.","\\(\\Pi_\\alpha=\\Pi+\\frac{\\alpha}{2}\\mathbf C^T\\mathbf C\\), for positive penalty \\(\\alpha\\).","\\(\\mathbf G=\\partial\\mathbf C/\\partial\\mathbf D\\), mapping DOF increments into constraint increments.","\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\)."],"correct":0},{"id":"c224","topic":"09_Constraints","question":"What does the constraint gradient G represent?","answer":"\\(\\mathbf G=\\partial\\mathbf C/\\partial\\mathbf D\\), mapping DOF increments into constraint increments.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["The derivative of constraint equations with respect to DOFs.","The derivative of mass density with respect to time.","The discrete Green strain tensor.","A matrix of contact friction coefficients only."],"correct":0},{"id":"c225","topic":"09_Constraints","question":"Why does a nonlinear constraint contribute additional tangent stiffness?","answer":"Its gradient changes with D, creating terms involving the Hessian of the constraint.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Its gradient changes with D, creating terms involving the Hessian of the constraint.","A condition applied to one DOF, such as a fixed displacement or prescribed motion.","\\(\\sum_i\\lambda_i\\,\\nabla^2 C_i\\), in addition to material tangent and constraint-gradient blocks.","Both force equilibrium and the constraint residual must be sufficiently small."],"correct":0},{"id":"c226","topic":"09_Constraints","question":"What is the nonlinear Lagrange multiplier tangent contribution?","answer":"\\(\\sum_i\\lambda_i\\,\\nabla^2 C_i\\), in addition to material tangent and constraint-gradient blocks.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["\\(\\sum_i\\lambda_i\\,\\nabla^2 C_i\\), in addition to material tangent and constraint-gradient blocks.","The generalized constraint reaction, with sign and units depending on how the constraint is defined.","\\(\\Pi^*(\\mathbf D,\\boldsymbol\\lambda)=\\Pi(\\mathbf D)+\\boldsymbol\\lambda^T\\mathbf C(\\mathbf D)\\).","Its gradient changes with D, creating terms involving the Hessian of the constraint."],"correct":0},{"id":"c227","topic":"09_Constraints","question":"Why can constraints require special convergence checks?","answer":"Both force equilibrium and the constraint residual must be sufficiently small.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Both force equilibrium and the constraint residual must be sufficiently small.","Constraint violation tends to zero, but numerical conditioning deteriorates.","Transformation (DOF elimination); Lagrange multipliers; penalty functions.","Dependent DOFs are eliminated, reducing system size without adding artificial stiffness."],"correct":0},{"id":"c228","topic":"09_Constraints","question":"How do you model an ideal hinge between beam groups using MPCs?","answer":"Tie translations while leaving the relative rotational DOF free.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["Tie translations; leave relative rotations unconstrained.","Tie all translations and rotations rigidly.","Release all translations while tying rotations.","Replace both beams with a single point mass."],"correct":0},{"id":"c229","topic":"09_Constraints","question":"What is a rigid element constraint intended to enforce?","answer":"A kinematic rigid-body displacement/rotation relation, not infinite stiffness through very large E.","source":"Lecture 10; Lecture 14; Exercise 10; Exercise 11; Exam 2021 P2; Exam 2022 P2; Exam 2019 P2","options":["A kinematic rigid-body displacement/rotation relation, not infinite stiffness through very large E.","A relation among multiple DOFs, such as tying two displacements or enforcing rigid-body motion.","\\(\\mathbf G=\\partial\\mathbf C/\\partial\\mathbf D\\), mapping DOF increments into constraint increments.","Constraints are enforced exactly at convergence, without selecting a large penalty stiffness."],"correct":0},{"id":"c230","topic":"10_Contact","question":"What is the unilateral contact condition?","answer":"Bodies may separate but must not penetrate each other; contact normal force cannot be tensile.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["No interpenetration, but separation is permitted.","Surfaces must always stay glued together.","Normal contact forces are allowed to pull surfaces together.","The gap must always be exactly zero everywhere."],"correct":0},{"id":"c231","topic":"10_Contact","question":"State normal contact complementarity using gap g and compression p.","answer":"\\(g_n\\ge0,\\ p_n\\ge0,\\ g_np_n=0\\) (positive gap and compressive pressure convention).","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["g ≥ 0, p ≥ 0, and gp = 0.","g ≤ 0, p ≥ 0, and gp = 1.","g ≥ 0, p ≤ 0, and gp > 0.","g = 0 and p = 0 everywhere."],"correct":0},{"id":"c232","topic":"10_Contact","question":"What does g > 0 mean in a gap formulation?","answer":"The contact surfaces are separated and the normal contact pressure is zero.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["The contact surfaces are separated and the normal contact pressure is zero.","Two contact surfaces are geometrically overlapping before the contact solve begins.","\\(g_n\\ge0,\\ p_n\\ge0,\\ g_np_n=0\\) (positive gap and compressive pressure convention).","The zero-gap condition applies only during active contact; separation must remain possible."],"correct":0},{"id":"c233","topic":"10_Contact","question":"What does g = 0 and p > 0 mean?","answer":"The surfaces are closed and carry a compressive normal contact force.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["The surfaces are closed and carry a compressive normal contact force.","A small penetration is required to generate the penalty contact force.","It opposes tangential sliding and dissipates mechanical energy.","Rapid artificial alternation between open and closed contact, often producing high-frequency force noise."],"correct":0},{"id":"c234","topic":"10_Contact","question":"Why is contact an inequality rather than an equality constraint?","answer":"The zero-gap condition applies only during active contact; separation must remain possible.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["The zero-gap condition applies only during active contact; separation must remain possible.","Rapid artificial alternation between open and closed contact, often producing high-frequency force noise.","Inspect gap/penetration, pressure, stick/slip status, contact forces, and global force/energy balance.","The contact surfaces are separated and the normal contact pressure is zero."],"correct":0},{"id":"c235","topic":"10_Contact","question":"What is the active-set approach to contact?","answer":"Iteratively determine which candidate contact constraints are active and enforce only those.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Identify currently contacting pairs, enforce them, and update the active set.","Keep every surface pair permanently tied from the start.","Solve contact only once using the undeformed geometry.","Switch all normal contact forces into tensile forces."],"correct":0},{"id":"c236","topic":"10_Contact","question":"Why is the tangent stiffness discontinuous when contact opens/closes?","answer":"The active constraint and associated contact stiffness are suddenly added or removed.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["The active constraint and associated contact stiffness are suddenly added or removed.","They enforce the active gap constraint without artificial penetration.","Iteratively determine which candidate contact constraints are active and enforce only those.","Two contact surfaces are geometrically overlapping before the contact solve begins."],"correct":0},{"id":"c237","topic":"10_Contact","question":"What is the difference between node-to-surface and surface-to-surface contact?","answer":"Node-to-surface enforces contact at slave nodes; surface-to-surface distributes the constraint more broadly over facets.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Node-to-surface constrains nodes; surface-to-surface distributes conditions over surfaces.","Both require one-to-one matching nodes on each surface.","Surface-to-surface contact never uses integration points.","Node-to-surface contact always enforces exact frictionless sticking."],"correct":0},{"id":"c238","topic":"10_Contact","question":"For node-to-surface contact, which body is usually chosen as master?","answer":"Usually the stiffer/coarser surface as master and softer/finer surface as slave.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Usually the stiffer/coarser surface as master and softer/finer surface as slave.","Node-to-surface enforces contact at slave nodes; surface-to-surface distributes the constraint more broadly over facets.","A coarse slave discretization can miss contact geometry and cause uneven pressure/penetration.","The active constraint and associated contact stiffness are suddenly added or removed."],"correct":0},{"id":"c239","topic":"10_Contact","question":"Why can poor master–slave selection reduce contact accuracy?","answer":"A coarse slave discretization can miss contact geometry and cause uneven pressure/penetration.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["A coarse slave discretization can miss contact geometry and cause uneven pressure/penetration.","It is a local traction derived from finite element discretization and contact constraint enforcement.","Iteratively determine which candidate contact constraints are active and enforce only those.","\\(g_n\\ge0,\\ p_n\\ge0,\\ g_np_n=0\\) (positive gap and compressive pressure convention)."],"correct":0},{"id":"c240","topic":"10_Contact","question":"Why is penalty contact never exactly nonpenetrating at finite stiffness?","answer":"A small penetration is required to generate the penalty contact force.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Finite penalty stiffness allows some small penetration.","A finite penalty always enforces the exact constraint.","Penalty forces are applied only when the gap is positive.","The contact penalty replaces the material constitutive law."],"correct":0},{"id":"c241","topic":"10_Contact","question":"How is contact normal force related to penetration in a simple penalty model?","answer":"\\(p_n=k_p\\,\\delta\\) when penetration \\(\\delta>0\\), and \\(p_n=0\\) when open.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["\\(p_n=k_p\\,\\delta\\) when penetration \\(\\delta>0\\), and \\(p_n=0\\) when open.","They enforce the active gap constraint without artificial penetration.","\\(g_n\\ge0,\\ p_n\\ge0,\\ g_np_n=0\\) (positive gap and compressive pressure convention).","Rapid artificial alternation between open and closed contact, often producing high-frequency force noise."],"correct":0},{"id":"c242","topic":"10_Contact","question":"What is the key penalty-contact parameter trade-off?","answer":"High penalty stiffness gives less penetration but worse conditioning and often a smaller explicit stable step.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["High penalty reduces penetration but worsens conditioning/stable Δt.","High penalty increases penetration and improves conditioning.","Low penalty always enforces perfect nonpenetration.","Penalty stiffness has no effect on numerical accuracy."],"correct":0},{"id":"c243","topic":"10_Contact","question":"Why are Lagrange multipliers attractive for contact?","answer":"They enforce the active gap constraint without artificial penetration.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["They enforce the active gap constraint without artificial penetration.","They add reaction unknowns and a saddle-point problem as contact activates and deactivates.","The zero-gap condition applies only during active contact; separation must remain possible.","The active constraint and associated contact stiffness are suddenly added or removed."],"correct":0},{"id":"c244","topic":"10_Contact","question":"Why may Lagrange multipliers complicate contact solution?","answer":"They add reaction unknowns and a saddle-point problem as contact activates and deactivates.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["They add reaction unknowns and a saddle-point problem as contact activates and deactivates.","They enforce the active gap constraint without artificial penetration.","The zero-gap condition applies only during active contact; separation must remain possible.","Iteratively determine which candidate contact constraints are active and enforce only those."],"correct":0},{"id":"c245","topic":"10_Contact","question":"What is the physical role of frictional contact traction?","answer":"It opposes tangential sliding and dissipates mechanical energy.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["It opposes tangential sliding and dissipates mechanical energy.","They enforce the active gap constraint without artificial penetration.","The contact surfaces are separated and the normal contact pressure is zero.","The surfaces are closed and carry a compressive normal contact force."],"correct":0},{"id":"c246","topic":"10_Contact","question":"State the Coulomb friction slip threshold.","answer":"\\(\\|\\mathbf t_t\\|\\le\\mu p_n\\); equality during sliding in an ideal Coulomb model.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["|t_t| ≤ μ p_n, with slip at the limiting friction traction.","|t_t| ≤ p_n/μ for every material.","t_t = 0 for all sliding contact.","The normal contact pressure must be tensile during slip."],"correct":0},{"id":"c247","topic":"10_Contact","question":"Why can contact cause convergence problems in implicit analysis?","answer":"Changing contact sets, frictional stick–slip, and sharp stiffness jumps make consistent linearization difficult.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Changing contact sets, frictional stick–slip, and sharp stiffness jumps make consistent linearization difficult.","Inspect gap/penetration, pressure, stick/slip status, contact forces, and global force/energy balance.","Rapid artificial alternation between open and closed contact, often producing high-frequency force noise.","They add reaction unknowns and a saddle-point problem as contact activates and deactivates."],"correct":0},{"id":"c248","topic":"10_Contact","question":"Why is explicit integration commonly robust for many-contact impact?","answer":"It avoids equilibrium iterations while contact forces are updated each small time step.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["It avoids equilibrium iterations while contact forces are updated each small time step.","Inspect gap/penetration, pressure, stick/slip status, contact forces, and global force/energy balance.","Two contact surfaces are geometrically overlapping before the contact solve begins.","The active constraint and associated contact stiffness are suddenly added or removed."],"correct":0},{"id":"c249","topic":"10_Contact","question":"What is initial overclosure?","answer":"Two contact surfaces are geometrically overlapping before the contact solve begins.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Two contact surfaces are geometrically overlapping before the contact solve begins.","The contact surfaces are separated and the normal contact pressure is zero.","The surfaces are closed and carry a compressive normal contact force.","It avoids equilibrium iterations while contact forces are updated each small time step."],"correct":0},{"id":"c250","topic":"10_Contact","question":"Why is contact pressure mesh-sensitive?","answer":"It is a local traction derived from finite element discretization and contact constraint enforcement.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["It is a local traction derived from finite element discretization and contact constraint enforcement.","A coarse slave discretization can miss contact geometry and cause uneven pressure/penetration.","Rapid artificial alternation between open and closed contact, often producing high-frequency force noise.","They add reaction unknowns and a saddle-point problem as contact activates and deactivates."],"correct":0},{"id":"c251","topic":"10_Contact","question":"What is contact chatter?","answer":"Rapid artificial alternation between open and closed contact, often producing high-frequency force noise.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Rapid artificial alternation between open and closed contact, often producing high-frequency force noise.","They add reaction unknowns and a saddle-point problem as contact activates and deactivates.","Bodies may separate but must not penetrate each other; contact normal force cannot be tensile.","High penalty stiffness gives less penetration but worse conditioning and often a smaller explicit stable step."],"correct":0},{"id":"c252","topic":"10_Contact","question":"How should contact constraints be checked in postprocessing?","answer":"Inspect gap/penetration, pressure, stick/slip status, contact forces, and global force/energy balance.","source":"Lecture 11; Lecture 10; Lecture 14; Exercise 10; Exam 2022 P4","options":["Inspect gap/penetration, pressure, stick/slip status, contact forces, and global force/energy balance.","Changing contact sets, frictional stick–slip, and sharp stiffness jumps make consistent linearization difficult.","It avoids equilibrium iterations while contact forces are updated each small time step.","The zero-gap condition applies only during active contact; separation must remain possible."],"correct":0},{"id":"c253","topic":"11_Finite_strain_and_TL_elements","question":"What is a reference configuration in finite deformation mechanics?","answer":"The configuration relative to which material coordinates and selected strain/stress measures are defined.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["The configuration to which material coordinates and selected strains refer.","Only the deformed current configuration.","A configuration used exclusively for free vibration.","The mesh after every nonlinear correction iteration."],"correct":0},{"id":"c254","topic":"11_Finite_strain_and_TL_elements","question":"What is the current configuration?","answer":"The spatial position and shape of the body at the considered state.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["The spatial position and shape of the body at the considered state.","Describe quantities at their current spatial coordinates x.","Test zero deformation and a pure rigid-body rotation; E_G must vanish for both.","\\(\\mathbf P=J\\boldsymbol\\sigma\\mathbf F^{-T}=\\mathbf F\\mathbf S\\)."],"correct":0},{"id":"c255","topic":"11_Finite_strain_and_TL_elements","question":"Define the Lagrangian description of motion.","answer":"Follow material points using their reference coordinates X.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Describe fields using the reference coordinates of material points.","Describe fields using current spatial coordinates only.","Ignore material-point correspondence during deformation.","Always assume small displacement gradients."],"correct":0},{"id":"c256","topic":"11_Finite_strain_and_TL_elements","question":"Define the Eulerian description of motion.","answer":"Describe quantities at their current spatial coordinates x.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Describe fields at current spatial positions.","Track fields only at reference coordinates.","Use a coordinate system that cannot rotate.","Use time as a replacement for every spatial coordinate."],"correct":0},{"id":"c257","topic":"11_Finite_strain_and_TL_elements","question":"Write the material-point displacement definition.","answer":"\\(\\mathbf u(\\mathbf X,t)=\\mathbf x(\\mathbf X,t)-\\mathbf X\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["u(X,t) = x(X,t) − X.","u(X,t) = x(X,t) + X.","u(X,t) = FᵀF.","u(X,t) = det(F)."],"correct":0},{"id":"c258","topic":"11_Finite_strain_and_TL_elements","question":"What does the deformation gradient F map?","answer":"Infinitesimal reference vectors into current ones: \\(d\\mathbf x=\\mathbf F\\,d\\mathbf X\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Infinitesimal material vectors dX to current vectors dx.","Stress to strain through Hooke’s law only.","Nodal forces to global equilibrium residuals.","Natural frequencies into time steps."],"correct":0},{"id":"c259","topic":"11_Finite_strain_and_TL_elements","question":"Define the deformation gradient.","answer":"\\(\\mathbf F=\\partial\\mathbf x/\\partial\\mathbf X=\\mathbf I+\\partial\\mathbf u/\\partial\\mathbf X\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["F = ∂x/∂X = I + ∂u/∂X.","F = ∂X/∂x = I − ∂u/∂X.","F = 1/2(FᵀF − I).","F = det(K_t)."],"correct":0},{"id":"c260","topic":"11_Finite_strain_and_TL_elements","question":"What is the displacement-gradient tensor H?","answer":"\\(\\mathbf H=\\partial\\mathbf u/\\partial\\mathbf X\\); thus \\(\\mathbf F=\\mathbf I+\\mathbf H\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(\\mathbf H=\\partial\\mathbf u/\\partial\\mathbf X\\); thus \\(\\mathbf F=\\mathbf I+\\mathbf H\\).","Infinitesimal reference vectors into current ones: \\(d\\mathbf x=\\mathbf F\\,d\\mathbf X\\).","\\(\\boldsymbol\\varepsilon=\\frac12(\\mathbf H+\\mathbf H^T)\\).","\\(\\mathbf R_{int}=EA_0L_0\\,E_G\\,\\partial E_G/\\partial\\mathbf D\\)."],"correct":0},{"id":"c261","topic":"11_Finite_strain_and_TL_elements","question":"What is J = det F?","answer":"The local ratio of deformed to reference volume; J > 0 is required for a valid deformation.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["The local change in volume (determinant of F).","The global tangent stiffness determinant.","The inverse Young modulus.","The mass-scaling factor in Abaqus."],"correct":0},{"id":"c262","topic":"11_Finite_strain_and_TL_elements","question":"How does density change under a finite deformation?","answer":"\\(\\rho=\\rho_0/J\\), from conservation of mass.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(\\rho=\\rho_0/J\\), from conservation of mass.","Second Piola–Kirchhoff stress S.","Describe quantities at their current spatial coordinates x.","\\(E_G=u/L_0+(u^2+v^2)/(2L_0^2)\\)."],"correct":0},{"id":"c263","topic":"11_Finite_strain_and_TL_elements","question":"Define the right Cauchy–Green tensor.","answer":"\\(\\mathbf C=\\mathbf F^T\\mathbf F\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["C = FᵀF.","C = FFᵀ.","C = F + Fᵀ.","C = (F − I)/2."],"correct":0},{"id":"c264","topic":"11_Finite_strain_and_TL_elements","question":"Define the Green–Lagrange strain tensor.","answer":"\\(\\mathbf E_G=\\frac12(\\mathbf F^T\\mathbf F-\\mathbf I)\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["E = (FᵀF − I)/2.","E = (F + Fᵀ)/2.","E = (FFᵀ + I)/2.","E = (F − Fᵀ)/2."],"correct":0},{"id":"c265","topic":"11_Finite_strain_and_TL_elements","question":"Express Green strain in terms of the displacement gradient H.","answer":"\\(\\mathbf E_G=\\frac12(\\mathbf H+\\mathbf H^T+\\mathbf H^T\\mathbf H)\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(\\mathbf E_G=\\frac12(\\mathbf H+\\mathbf H^T+\\mathbf H^T\\mathbf H)\\).","\\(\\mathbf S=\\lambda_L\\,\\mathrm{tr}(\\mathbf E_G)\\mathbf I+2\\mu\\mathbf E_G\\).","\\(\\mathbf F=\\partial\\mathbf x/\\partial\\mathbf X=\\mathbf I+\\partial\\mathbf u/\\partial\\mathbf X\\).","Infinitesimal reference vectors into current ones: \\(d\\mathbf x=\\mathbf F\\,d\\mathbf X\\)."],"correct":0},{"id":"c266","topic":"11_Finite_strain_and_TL_elements","question":"What is the infinitesimal strain tensor?","answer":"\\(\\boldsymbol\\varepsilon=\\frac12(\\mathbf H+\\mathbf H^T)\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["ε = (H + Hᵀ)/2, with H = ∂u/∂X.","ε = (FᵀF − I)/2 for all small strains only.","ε = det(F).","ε = (H − Hᵀ)/2."],"correct":0},{"id":"c267","topic":"11_Finite_strain_and_TL_elements","question":"What is the essential difference between Green and infinitesimal strains?","answer":"Green strain includes \\(\\frac12\\mathbf H^T\\mathbf H\\), which becomes important at finite rotations/deformations.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Green strain includes \\(\\frac12\\mathbf H^T\\mathbf H\\), which becomes important at finite rotations/deformations.","\\(\\mathbf E_G=\\frac12(\\mathbf H+\\mathbf H^T+\\mathbf H^T\\mathbf H)\\).","No. It generally predicts artificial strain; Green strain vanishes for F = R with RᵀR = I.","\\(\\boldsymbol\\varepsilon=\\frac12(\\mathbf H+\\mathbf H^T)\\)."],"correct":0},{"id":"c268","topic":"11_Finite_strain_and_TL_elements","question":"Why is objective strain necessary in large-rotation analysis?","answer":"A superposed rigid-body translation/rotation must not create spurious deformation strain.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Rigid rotations must not create spurious material strain.","Rigid rotations should always produce large shear strain.","Only the elastic modulus needs to remain constant.","Finite deformation always produces plastic strain."],"correct":0},{"id":"c269","topic":"11_Finite_strain_and_TL_elements","question":"Does infinitesimal strain vanish under arbitrary finite rigid-body rotation?","answer":"No. It generally predicts artificial strain; Green strain vanishes for F = R with RᵀR = I.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["No. It can predict spurious strain under large rigid rotation.","Yes, for every finite rigid-body rotation.","Yes, but only if the material is nonlinear.","No, because it is undefined for all 2D elements."],"correct":0},{"id":"c270","topic":"11_Finite_strain_and_TL_elements","question":"What is the Green strain of a 1D bar from lengths L and L₀?","answer":"\\(E_G=(L^2-L_0^2)/(2L_0^2)\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["E_G = (L² − L₀²)/(2L₀²).","E_G = (L − L₀)/L₀ only.","E_G = (L₀² − L²)/(L²).","E_G = (L² + L₀²)/(2L₀²)."],"correct":0},{"id":"c271","topic":"11_Finite_strain_and_TL_elements","question":"What is engineering axial strain from bar lengths?","answer":"\\(e=(L-L_0)/L_0\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["e = (L − L₀)/L₀.","e = (L² − L₀²)/(2L₀²).","e = (L + L₀)/L₀.","e = (L₀ − L)/L."],"correct":0},{"id":"c272","topic":"11_Finite_strain_and_TL_elements","question":"Relate 1D Green strain E_G to engineering strain e.","answer":"\\(E_G=e+\\tfrac12e^2\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["E_G = e + e²/2.","E_G = e − e²/2.","E_G = e²/2 only.","E_G = 2e + e²."],"correct":0},{"id":"c273","topic":"11_Finite_strain_and_TL_elements","question":"When do engineering and Green axial strain become nearly equal?","answer":"For small axial strain, because the quadratic term e²/2 becomes negligible.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["For small axial strain, because the quadratic term e²/2 becomes negligible.","The deformed length is \\(L=\\sqrt{(L_0+u)^2+v^2}\\); the v² term increases length.","No. It generally predicts artificial strain; Green strain vanishes for F = R with RᵀR = I.","\\(U=\\tfrac12 E A_0L_0 E_G^2\\) for uniform axial Green strain."],"correct":0},{"id":"c274","topic":"11_Finite_strain_and_TL_elements","question":"Why can a transverse displacement stretch an initially horizontal bar?","answer":"The deformed length is \\(L=\\sqrt{(L_0+u)^2+v^2}\\); the v² term increases length.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["A transverse shift increases the bar length even without axial movement.","Transverse displacement never changes bar length.","Only material plasticity causes bar extension.","Engineering strain includes only shear deformation."],"correct":0},{"id":"c275","topic":"11_Finite_strain_and_TL_elements","question":"What is the plane 2-node bar Green strain for nodal displacement (u,v) at the free end?","answer":"\\(E_G=u/L_0+(u^2+v^2)/(2L_0^2)\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(E_G=u/L_0+(u^2+v^2)/(2L_0^2)\\).","\\(e=(L-L_0)/L_0\\).","\\(E_G=e+\\tfrac12e^2\\).","Second Piola–Kirchhoff stress S."],"correct":0},{"id":"c276","topic":"11_Finite_strain_and_TL_elements","question":"What is the basic requirement on a finite-strain measure under rigid-body motion?","answer":"It must be zero for pure rigid motion and transform objectively under superposed rotation.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["It gives zero strain under pure rigid translation or rotation.","It must increase linearly with rigid-body rotation.","It must predict nonzero Cauchy stress for any translation.","It changes with the choice of observer."],"correct":0},{"id":"c277","topic":"11_Finite_strain_and_TL_elements","question":"Why must stresses and strains be work conjugate?","answer":"Their virtual work must represent the same internal energy independently of description or configuration.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Their virtual work must represent the same internal energy independently of description or configuration.","The configuration relative to which material coordinates and selected strain/stress measures are defined.","Green strain includes \\(\\frac12\\mathbf H^T\\mathbf H\\), which becomes important at finite rotations/deformations.","Kinematics and equilibrium are updated using the most recent configuration as reference."],"correct":0},{"id":"c278","topic":"11_Finite_strain_and_TL_elements","question":"Which stress is work-conjugate to Green strain in the reference configuration?","answer":"Second Piola–Kirchhoff stress S.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Second Piola–Kirchhoff stress S.","Cauchy stress σ without any configuration change.","The force residual R_res.","The lumped mass matrix M."],"correct":0},{"id":"c279","topic":"11_Finite_strain_and_TL_elements","question":"What is the true (Cauchy) stress?","answer":"Force per unit area of a surface in the current deformed configuration.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Force per unit area of a surface in the current deformed configuration.","\\(\\boldsymbol\\sigma=J^{-1}\\mathbf F\\mathbf S\\mathbf F^T\\).","For small axial strain, because the quadratic term e²/2 becomes negligible.","Kinematics and equilibrium are updated using the most recent configuration as reference."],"correct":0},{"id":"c280","topic":"11_Finite_strain_and_TL_elements","question":"How are Cauchy stress σ and second Piola–Kirchhoff stress S related?","answer":"\\(\\boldsymbol\\sigma=J^{-1}\\mathbf F\\mathbf S\\mathbf F^T\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["σ = J⁻¹ F S Fᵀ.","σ = J Fᵀ S F.","σ = F⁻¹ S F⁻ᵀ.","σ = S + F only."],"correct":0},{"id":"c281","topic":"11_Finite_strain_and_TL_elements","question":"What is the first Piola–Kirchhoff stress?","answer":"\\(\\mathbf P=J\\boldsymbol\\sigma\\mathbf F^{-T}=\\mathbf F\\mathbf S\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(\\mathbf P=J\\boldsymbol\\sigma\\mathbf F^{-T}=\\mathbf F\\mathbf S\\).","\\(\\boldsymbol\\varepsilon=\\frac12(\\mathbf H+\\mathbf H^T)\\).","\\(\\mathbf F=\\partial\\mathbf x/\\partial\\mathbf X=\\mathbf I+\\partial\\mathbf u/\\partial\\mathbf X\\).","Infinitesimal reference vectors into current ones: \\(d\\mathbf x=\\mathbf F\\,d\\mathbf X\\)."],"correct":0},{"id":"c282","topic":"11_Finite_strain_and_TL_elements","question":"What is the linear St. Venant–Kirchhoff material law?","answer":"\\(\\mathbf S=\\lambda_L\\,\\mathrm{tr}(\\mathbf E_G)\\mathbf I+2\\mu\\mathbf E_G\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["S = λ tr(E)I + 2μE.","S = E + FᵀF.","S = M D¨ + C D˙.","S = K_m + λ K_g."],"correct":0},{"id":"c283","topic":"11_Finite_strain_and_TL_elements","question":"Why can a linearly elastic constitutive relation still yield nonlinear force–displacement behavior?","answer":"The strain measure and internal force depend nonlinearly on the displacement and changing geometry.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["The strain measure and internal force depend nonlinearly on the displacement and changing geometry.","Their virtual work must represent the same internal energy independently of description or configuration.","Interpolation that maps a standard ξ,η element domain to the actual element geometry.","All integrals, strain measures, and selected stress descriptions refer to the original configuration."],"correct":0},{"id":"c284","topic":"11_Finite_strain_and_TL_elements","question":"What distinguishes Total Lagrangian (TL) formulation?","answer":"All integrals, strain measures, and selected stress descriptions refer to the original configuration.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["The reference configuration is fixed at the initial state.","The reference is updated to the current state each increment.","All strains are assumed infinitesimal even during large rotations.","Only the Eulerian velocity field is interpolated."],"correct":0},{"id":"c285","topic":"11_Finite_strain_and_TL_elements","question":"What distinguishes Updated Lagrangian (UL) formulation?","answer":"Kinematics and equilibrium are updated using the most recent configuration as reference.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Use the most recently updated configuration as reference.","Always use the original undeformed configuration.","Ignore rigid-body rotation from one increment to the next.","Replace Green strain with kinetic energy."],"correct":0},{"id":"c286","topic":"11_Finite_strain_and_TL_elements","question":"What distinguishes a corotational formulation?","answer":"Remove element rigid-body rotation and compute deformational response in a rotating local frame.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Separate rigid-body rotation from local deformational response.","Treat every rigid rotation as a plastic deformation.","Use only the linear reference stiffness from the initial state.","Avoid any finite-element coordinate transformation."],"correct":0},{"id":"c287","topic":"11_Finite_strain_and_TL_elements","question":"What is the strain energy of a TL bar with linear S = E E_G?","answer":"\\(U=\\tfrac12 E A_0L_0 E_G^2\\) for uniform axial Green strain.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(U=\\tfrac12 E A_0L_0 E_G^2\\) for uniform axial Green strain.","\\(\\mathbf R_{int}=EA_0L_0\\,E_G\\,\\partial E_G/\\partial\\mathbf D\\).","\\(\\mathbf E_G=\\frac12(\\mathbf H+\\mathbf H^T+\\mathbf H^T\\mathbf H)\\).","Variation of strain–displacement coupling with deformation, weighted by the current stress."],"correct":0},{"id":"c288","topic":"11_Finite_strain_and_TL_elements","question":"How is the internal force obtained for a TL bar?","answer":"\\(\\mathbf R_{int}=EA_0L_0\\,E_G\\,\\partial E_G/\\partial\\mathbf D\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(\\mathbf R_{int}=EA_0L_0\\,E_G\\,\\partial E_G/\\partial\\mathbf D\\).","\\(\\mathbf F=\\partial\\mathbf x/\\partial\\mathbf X=\\mathbf I+\\partial\\mathbf u/\\partial\\mathbf X\\).","\\(\\mathbf E_G=\\frac12(\\mathbf H+\\mathbf H^T+\\mathbf H^T\\mathbf H)\\).","\\(\\mathbf K_t=\\mathbf K_{material}+\\mathbf K_{geometric}\\)."],"correct":0},{"id":"c289","topic":"11_Finite_strain_and_TL_elements","question":"How is a TL bar tangent stiffness split conceptually?","answer":"\\(\\mathbf K_t=\\mathbf K_{material}+\\mathbf K_{geometric}\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(\\mathbf K_t=\\mathbf K_{material}+\\mathbf K_{geometric}\\).","\\(\\mathbf E_G=\\frac12(\\mathbf F^T\\mathbf F-\\mathbf I)\\).","\\(\\mathbf R_{int}=EA_0L_0\\,E_G\\,\\partial E_G/\\partial\\mathbf D\\).","\\(U=\\tfrac12 E A_0L_0 E_G^2\\) for uniform axial Green strain."],"correct":0},{"id":"c290","topic":"11_Finite_strain_and_TL_elements","question":"What causes the material part of a TL bar tangent stiffness?","answer":"Variation of stress due to variation of strain: a constitutive term involving strain derivatives.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Variation of stress due to variation of strain: a constitutive term involving strain derivatives.","\\(\\mathbf K_t=\\mathbf K_{material}+\\mathbf K_{geometric}\\).","No. It generally predicts artificial strain; Green strain vanishes for F = R with RᵀR = I.","All integrals, strain measures, and selected stress descriptions refer to the original configuration."],"correct":0},{"id":"c291","topic":"11_Finite_strain_and_TL_elements","question":"What causes the geometric part of a TL bar tangent stiffness?","answer":"Variation of strain–displacement coupling with deformation, weighted by the current stress.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Variation of strain–displacement coupling with deformation, weighted by the current stress.","\\(\\mathbf K_t=\\mathbf K_{material}+\\mathbf K_{geometric}\\).","\\(U=\\tfrac12 E A_0L_0 E_G^2\\) for uniform axial Green strain.","\\(\\mathbf R_{int}=EA_0L_0\\,E_G\\,\\partial E_G/\\partial\\mathbf D\\)."],"correct":0},{"id":"c292","topic":"11_Finite_strain_and_TL_elements","question":"What is a parent-element (natural-coordinate) mapping?","answer":"Interpolation that maps a standard ξ,η element domain to the actual element geometry.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Interpolation that maps a standard ξ,η element domain to the actual element geometry.","A zero/negative determinant means a collapsed or inverted element mapping.","Infinitesimal reference vectors into current ones: \\(d\\mathbf x=\\mathbf F\\,d\\mathbf X\\).","Differentiate shape functions in natural coordinates, then transform using the inverse reference Jacobian."],"correct":0},{"id":"c293","topic":"11_Finite_strain_and_TL_elements","question":"What is the purpose of the isoparametric Jacobian J₀?","answer":"It transforms derivatives and integration measures between natural coordinates and material coordinates.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["It maps derivatives and integration between natural and material coordinates.","It converts the tangent stiffness into consistent mass.","It scales the yield stress in plasticity.","It defines the time step in explicit integration."],"correct":0},{"id":"c294","topic":"11_Finite_strain_and_TL_elements","question":"How do you compute displacement gradients in an isoparametric element?","answer":"Differentiate shape functions in natural coordinates, then transform using the inverse reference Jacobian.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Differentiate shape functions in natural coordinates, then transform using the inverse reference Jacobian.","It transforms derivatives and integration measures between natural coordinates and material coordinates.","A zero/negative determinant means a collapsed or inverted element mapping.","The strain measure and internal force depend nonlinearly on the displacement and changing geometry."],"correct":0},{"id":"c295","topic":"11_Finite_strain_and_TL_elements","question":"What shape functions are used for a bilinear 4-node quadrilateral?","answer":"\\(N_i=\\tfrac14(1+\\xi_i\\xi)(1+\\eta_i\\eta)\\).","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["\\(N_i=\\tfrac14(1+\\xi_i\\xi)(1+\\eta_i\\eta)\\).","Describe quantities at their current spatial coordinates x.","Second Piola–Kirchhoff stress S.","\\(\\rho=\\rho_0/J\\), from conservation of mass."],"correct":0},{"id":"c296","topic":"11_Finite_strain_and_TL_elements","question":"Why must an isoparametric element Jacobian be positive?","answer":"A zero/negative determinant means a collapsed or inverted element mapping.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Zero or negative determinant indicates collapsed/inverted mapping.","It guarantees the Jacobian is a symmetric matrix.","It is required only for lumped mass matrices.","It ensures the plastic multiplier remains positive."],"correct":0},{"id":"c297","topic":"11_Finite_strain_and_TL_elements","question":"How can one verify a computed finite-strain tensor?","answer":"Test zero deformation and a pure rigid-body rotation; E_G must vanish for both.","source":"Lecture 12; Lecture 14; Exercise 11; Exercise 12; Exam 2019 P1-P4; Exam 2022 P2-P5; Exam 2023 P1-P4; Exam 2024 P1-P2; Exam 2025 P1-P3","options":["Test zero deformation and a pure rigid-body rotation; E_G must vanish for both.","It must be zero for pure rigid motion and transform objectively under superposed rotation.","A superposed rigid-body translation/rotation must not create spurious deformation strain.","Remove element rigid-body rotation and compute deformational response in a rotating local frame."],"correct":0},{"id":"c298","topic":"12_Stress_stiffness_buckling","question":"What is the physical meaning of geometric (stress) stiffness?","answer":"The change in incremental structural stiffness caused by an existing stress or membrane force state.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Incremental stiffness caused by the current stress state.","Stiffness independent of geometry and stress.","The damping added by the Newmark method.","The inverse of the consistent mass matrix."],"correct":0},{"id":"c299","topic":"12_Stress_stiffness_buckling","question":"How does axial compression affect lateral stiffness?","answer":"It reduces effective lateral stiffness and can cause buckling.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Compression decreases lateral tangent stiffness, promoting buckling.","Compression always increases lateral stiffness.","Compression changes only material density.","Compression does not affect geometric stiffness."],"correct":0},{"id":"c300","topic":"12_Stress_stiffness_buckling","question":"How does axial tension affect lateral stiffness?","answer":"It generally increases lateral stiffness (stress stiffening).","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Tension generally increases lateral tangent stiffness.","Tension always decreases lateral stiffness.","Tension has no geometric effect.","Tension causes all modes to bifurcate."],"correct":0},{"id":"c301","topic":"12_Stress_stiffness_buckling","question":"Write the tangent stiffness split for a structure with geometric effects.","answer":"\\(\\mathbf K_t=\\mathbf K_m+\\mathbf K_g\\), with material and geometric contributions.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["K_t = K_m + K_g.","K_t = M + C.","K_t = K_m K_g.","K_t = K_m − M⁻¹."],"correct":0},{"id":"c302","topic":"12_Stress_stiffness_buckling","question":"What is the key mathematical signal of classical static buckling?","answer":"A tangent-stiffness eigenvalue approaches zero: the structure loses stiffness in a mode.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["The tangent stiffness becomes singular.","The initial Young modulus becomes infinite.","The mass matrix becomes exactly zero.","The Green strain vanishes everywhere."],"correct":0},{"id":"c303","topic":"12_Stress_stiffness_buckling","question":"Write the linearized buckling eigenvalue problem.","answer":"\\((\\mathbf K_m+\\lambda_j\\mathbf K_g^{ref})\\boldsymbol\\phi_j=\\mathbf0\\).","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["(K_m + λK_g) φ = 0.","(K_m − ω²M) φ = R_ext.","K_t ΔD = R_res.","M D¨ + C D˙ + K D = R(t)."],"correct":0},{"id":"c304","topic":"12_Stress_stiffness_buckling","question":"What does a buckling eigenvalue λ represent?","answer":"The factor multiplying the reference load at which the linearized model has a buckling mode.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["The load factor multiplying the reference load at buckling.","The increment in plastic hardening only.","The ratio of kinetic and internal energies.","The inverse determinant of the mass matrix."],"correct":0},{"id":"c305","topic":"12_Stress_stiffness_buckling","question":"What is the buckling load factor (BLF)?","answer":"\\(BLF=P_{cr}/P_{ref}=\\lambda_{cr}\\), given the load used to form geometric stiffness.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["BLF = P_cr/P_ref = λ_cr.","BLF = P_ref/P_cr = 1/λ_cr.","BLF = K_t/M.","BLF = L²/EI."],"correct":0},{"id":"c306","topic":"12_Stress_stiffness_buckling","question":"What does a buckling eigenvector represent?","answer":"A possible instability deformation mode; its amplitude is arbitrary in linear eigenvalue buckling.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["The linearized buckling mode shape.","The physical load duration.","A vector of initial support reactions.","The assembled residual force under prescribed loads."],"correct":0},{"id":"c307","topic":"12_Stress_stiffness_buckling","question":"Give the Euler buckling load for a pinned–pinned column.","answer":"\\(P_{cr}=\\pi^2EI/L^2\\).","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["P_cr = π²EI/L² for pinned–pinned ends.","P_cr = πEI/L.","P_cr = 4π²EI/L² for pinned–pinned ends.","P_cr = EA/L for all columns."],"correct":0},{"id":"c308","topic":"12_Stress_stiffness_buckling","question":"How does effective column length influence Euler buckling load?","answer":"\\(P_{cr}=\\pi^2EI/(KL)^2\\); doubling effective length reduces critical load by four.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["\\(P_{cr}=\\pi^2EI/(KL)^2\\); doubling effective length reduces critical load by four.","\\(BLF=P_{cr}/P_{ref}=\\lambda_{cr}\\), given the load used to form geometric stiffness.","It reduces effective lateral stiffness and can cause buckling.","It makes the tangent singular or nearly singular even before external load is applied."],"correct":0},{"id":"c309","topic":"12_Stress_stiffness_buckling","question":"What is the difference between eigenvalue buckling and nonlinear postbuckling?","answer":"Eigenvalue buckling estimates critical load/mode around a reference state; postbuckling traces actual deformed equilibrium.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Eigenvalue buckling is linearized; postbuckling traces nonlinear response.","Eigenvalue buckling directly predicts all plastic collapse modes.","Postbuckling assumes zero initial stress and no displacement.","Both methods always give identical load–deflection paths."],"correct":0},{"id":"c310","topic":"12_Stress_stiffness_buckling","question":"Why might a perfect symmetric model remain on an unstable primary branch?","answer":"Without imperfections or numerical perturbations, it may preserve symmetry and not activate an asymmetric mode.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Without imperfections or numerical perturbations, it may preserve symmetry and not activate an asymmetric mode.","Locally stable equilibrium under the usual energy criterion, subject to admissible perturbations.","A real stiffness eigenvalue reaches zero, allowing steadily growing displacement in a mode.","They can change or eliminate ideal bifurcations and greatly lower the maximum load of imperfection-sensitive systems."],"correct":0},{"id":"c311","topic":"12_Stress_stiffness_buckling","question":"Why do geometric imperfections matter in buckling?","answer":"They can change or eliminate ideal bifurcations and greatly lower the maximum load of imperfection-sensitive systems.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["They can strongly affect predicted loads and postbuckling path.","They always increase the buckling load.","They matter only for mass scaling in explicit dynamics.","They eliminate all possibility of local buckling."],"correct":0},{"id":"c312","topic":"12_Stress_stiffness_buckling","question":"What is a key assumption of linearized prebuckling analysis (LPB)?","answer":"The reference geometry changes negligibly before buckling and the load/stress distribution scales linearly.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["The reference geometry changes negligibly before buckling and the load/stress distribution scales linearly.","It may substantially overpredict buckling strength because shells can be extremely imperfection-sensitive.","The load vector changes with displacement, and its derivative need not be symmetric.","A tangent-stiffness eigenvalue approaches zero: the structure loses stiffness in a mode."],"correct":0},{"id":"c313","topic":"12_Stress_stiffness_buckling","question":"What is a key limitation of LPB for shells?","answer":"It may substantially overpredict buckling strength because shells can be extremely imperfection-sensitive.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["It may substantially overpredict buckling strength because shells can be extremely imperfection-sensitive.","They can change or eliminate ideal bifurcations and greatly lower the maximum load of imperfection-sensitive systems.","The reference geometry changes negligibly before buckling and the load/stress distribution scales linearly.","A tangent-stiffness eigenvalue approaches zero: the structure loses stiffness in a mode."],"correct":0},{"id":"c314","topic":"12_Stress_stiffness_buckling","question":"Why can LPB also underestimate actual buckling load?","answer":"Prebuckling tension or stabilizing geometric nonlinearities ignored in LPB can stiffen the real structure.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Prebuckling tension or stabilizing geometric nonlinearities ignored in LPB can stiffen the real structure.","It neglects imperfections, material yielding, large prebuckling changes, and possible contact or other failure mechanisms.","The reference geometry changes negligibly before buckling and the load/stress distribution scales linearly.","Nonconservative systems can suffer oscillatory flutter before any zero static stiffness eigenvalue appears."],"correct":0},{"id":"c315","topic":"12_Stress_stiffness_buckling","question":"What is static instability by divergence?","answer":"A real stiffness eigenvalue reaches zero, allowing steadily growing displacement in a mode.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["A real stiffness eigenvalue reaches zero, allowing steadily growing displacement in a mode.","A tangent-stiffness eigenvalue approaches zero: the structure loses stiffness in a mode.","Coupled modes acquire growing oscillations, typically associated with complex dynamic eigenvalues.","Nonconservative systems can suffer oscillatory flutter before any zero static stiffness eigenvalue appears."],"correct":0},{"id":"c316","topic":"12_Stress_stiffness_buckling","question":"What is dynamic instability by flutter?","answer":"Coupled modes acquire growing oscillations, typically associated with complex dynamic eigenvalues.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Coupled modes acquire growing oscillations, typically associated with complex dynamic eigenvalues.","A real stiffness eigenvalue reaches zero, allowing steadily growing displacement in a mode.","Prebuckling tension or stabilizing geometric nonlinearities ignored in LPB can stiffen the real structure.","It makes the tangent singular or nearly singular even before external load is applied."],"correct":0},{"id":"c317","topic":"12_Stress_stiffness_buckling","question":"What is the difference between conservative and follower loading?","answer":"Conservative loads have a displacement potential; follower loads track deformation and generally lack a potential.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Follower-load direction/configuration changes with deformation.","Dead loads always rotate with the element.","Conservative loads have no potential function.","Follower loads cannot create geometric stiffness."],"correct":0},{"id":"c318","topic":"12_Stress_stiffness_buckling","question":"Why can a follower load create a nonsymmetric tangent stiffness?","answer":"The load vector changes with displacement, and its derivative need not be symmetric.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["The derivative of deformation-dependent loading need not be symmetric.","All follower loads are normal to every element simultaneously.","The consistent mass matrix becomes nonsymmetric.","Only plasticity can create nonsymmetric tangent stiffness."],"correct":0},{"id":"c319","topic":"12_Stress_stiffness_buckling","question":"What is load-correction stiffness?","answer":"\\(\\mathbf K_{load}=-\\partial\\mathbf R_{ext}/\\partial\\mathbf D\\) in a tangent written as internal minus external derivative.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["\\(\\mathbf K_{load}=-\\partial\\mathbf R_{ext}/\\partial\\mathbf D\\) in a tangent written as internal minus external derivative.","\\(\\mathbf K_t=\\mathbf K_m+\\mathbf K_g\\), with material and geometric contributions.","It neglects imperfections, material yielding, large prebuckling changes, and possible contact or other failure mechanisms.","Eigenvalue buckling estimates critical load/mode around a reference state; postbuckling traces actual deformed equilibrium."],"correct":0},{"id":"c320","topic":"12_Stress_stiffness_buckling","question":"What is the tangent for configuration-dependent external load?","answer":"\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D-\\partial\\mathbf R_{ext}/\\partial\\mathbf D\\).","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["K_t = ∂R_int/∂D − ∂R_ext/∂D.","K_t = ∂R_int/∂D + ∂R_ext/∂D.","K_t = M + K_g.","K_t = R_ext − R_int."],"correct":0},{"id":"c321","topic":"12_Stress_stiffness_buckling","question":"Why can static buckling criteria be insufficient for follower forces?","answer":"Nonconservative systems can suffer oscillatory flutter before any zero static stiffness eigenvalue appears.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Nonconservative systems can suffer oscillatory flutter before any zero static stiffness eigenvalue appears.","A tangent-stiffness eigenvalue approaches zero: the structure loses stiffness in a mode.","They can change or eliminate ideal bifurcations and greatly lower the maximum load of imperfection-sensitive systems.","A real stiffness eigenvalue reaches zero, allowing steadily growing displacement in a mode."],"correct":0},{"id":"c322","topic":"12_Stress_stiffness_buckling","question":"What does positive definiteness of tangent stiffness imply in conservative static equilibrium?","answer":"Locally stable equilibrium under the usual energy criterion, subject to admissible perturbations.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Locally stable equilibrium under the usual energy criterion, subject to admissible perturbations.","\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D-\\partial\\mathbf R_{ext}/\\partial\\mathbf D\\).","Conservative loads have a displacement potential; follower loads track deformation and generally lack a potential.","A possible instability deformation mode; its amplitude is arbitrary in linear eigenvalue buckling."],"correct":0},{"id":"c323","topic":"12_Stress_stiffness_buckling","question":"Why is a zero-energy mechanism difficult for Newton iterations?","answer":"It makes the tangent singular or nearly singular even before external load is applied.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["It makes the tangent singular or nearly singular even before external load is applied.","\\(BLF=P_{cr}/P_{ref}=\\lambda_{cr}\\), given the load used to form geometric stiffness.","The load vector changes with displacement, and its derivative need not be symmetric.","The change in incremental structural stiffness caused by an existing stress or membrane force state."],"correct":0},{"id":"c324","topic":"12_Stress_stiffness_buckling","question":"How can an initially slack cable be stabilized numerically?","answer":"Introduce appropriate pretension, gravity, geometric stabilization, or a compatible initial loading procedure.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["Introduce appropriate pretension, gravity, geometric stabilization, or a compatible initial loading procedure.","\\(\\mathbf K_t=\\partial\\mathbf R_{int}/\\partial\\mathbf D-\\partial\\mathbf R_{ext}/\\partial\\mathbf D\\).","Without imperfections or numerical perturbations, it may preserve symmetry and not activate an asymmetric mode.","\\(BLF=P_{cr}/P_{ref}=\\lambda_{cr}\\), given the load used to form geometric stiffness."],"correct":0},{"id":"c325","topic":"12_Stress_stiffness_buckling","question":"Why can force-controlled buckling computations jump to an unwanted response?","answer":"The equilibrium path may become unstable or nonunique near a limit/bifurcation point.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["The equilibrium path may become unstable or nonunique near a limit/bifurcation point.","\\((\\mathbf K_m+\\lambda_j\\mathbf K_g^{ref})\\boldsymbol\\phi_j=\\mathbf0\\).","Nonconservative systems can suffer oscillatory flutter before any zero static stiffness eigenvalue appears.","Coupled modes acquire growing oscillations, typically associated with complex dynamic eigenvalues."],"correct":0},{"id":"c326","topic":"12_Stress_stiffness_buckling","question":"Why is a linear buckling load not automatically the true failure load?","answer":"It neglects imperfections, material yielding, large prebuckling changes, and possible contact or other failure mechanisms.","source":"Lecture 13; Lecture 14; Exercise 2; Exercise 11; Exercise 12; Exam 2019 P1; Exam 2021 P1; Exam 2022 P1; Exam 2023 P2-P4","options":["It neglects imperfections, nonlinear prebuckling, and possible yielding.","Linear buckling always gives the exact material failure load.","The first buckling mode must always be physically stable.","The Euler critical load is independent of boundary conditions."],"correct":0},{"id":"c327","topic":"13_Exam_practice_and_Abaqus","question":"What does NLGEOM change in an Abaqus static step?","answer":"It enables a geometrically nonlinear formulation that accounts for the deformed configuration.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["It includes geometrically nonlinear effects from deformation.","It switches the solver from implicit to explicit.","It automatically activates plasticity in every material.","It replaces all beam elements with continuum elements."],"correct":0},{"id":"c328","topic":"13_Exam_practice_and_Abaqus","question":"What does a Static, Riks procedure target?","answer":"Unstable equilibrium paths including descending load segments and snap-through.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Unstable nonlinear equilibrium paths, including snap-through.","Only the linear undamped eigenvalue problem.","Explicit dynamic impact trajectories without iteration.","The local stress update of a J2 plastic material."],"correct":0},{"id":"c329","topic":"13_Exam_practice_and_Abaqus","question":"What is the conceptual difference between Abaqus/Standard and Abaqus/Explicit?","answer":"Standard solves coupled equilibrium iteratively; Explicit advances dynamics with small stable steps.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Standard uses implicit equilibrium solves; Explicit uses small explicit steps.","Standard always uses diagonal mass; Explicit always uses consistent mass.","Standard cannot model contact; Explicit cannot model plasticity.","Both use identical Newton solves at each time increment."],"correct":0},{"id":"c330","topic":"13_Exam_practice_and_Abaqus","question":"Why do B23 beam elements differ from B21?","answer":"B23 uses cubic Euler–Bernoulli bending interpolation; B21 is a linear Timoshenko beam including shear effects.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["B23 uses cubic Euler–Bernoulli bending interpolation; B21 is a linear Timoshenko beam including shear effects.","Reactions and displacements from the wrong node or reference point can give a plausible but incorrect curve.","Underintegration can permit zero-energy deformation modes stabilized numerically rather than physically.","Use a uniaxial loading–unloading cycle and verify the elastic slope, yield condition, and residual strain."],"correct":0},{"id":"c331","topic":"13_Exam_practice_and_Abaqus","question":"Why can a shallow arch with plasticity carry less peak load than an elastic arch?","answer":"Yielding reduces tangent stiffness and the load capacity before/during geometric instability.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Yielding reduces tangent stiffness and the load capacity before/during geometric instability.","Geometry, material, and boundary/loading response are rotationally symmetric about an axis.","It enables a geometrically nonlinear formulation that accounts for the deformed configuration.","More converged points resolve sharp nonlinear changes and critical points."],"correct":0},{"id":"c332","topic":"13_Exam_practice_and_Abaqus","question":"Why does reducing maximum static increment improve a load–displacement curve?","answer":"More converged points resolve sharp nonlinear changes and critical points.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["More converged points resolve sharp nonlinear changes and critical points.","It enables a geometrically nonlinear formulation that accounts for the deformed configuration.","A converged load–displacement or time-history solution, not iteration count alone.","Unstable equilibrium paths including descending load segments and snap-through."],"correct":0},{"id":"c333","topic":"13_Exam_practice_and_Abaqus","question":"How should total reaction be recovered in a symmetric half-model?","answer":"Multiply the reaction from the half model by two when the full model consists of two identical symmetric halves.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Multiply the reaction from the half model by two when the full model consists of two identical symmetric halves.","For linear limits or simplified configurations where closed-form deflections/rotations are available.","Reactions and displacements from the wrong node or reference point can give a plausible but incorrect curve.","Inaccurate pressure distributions, localization, stress gradients, and predicted load–deflection behavior."],"correct":0},{"id":"c334","topic":"13_Exam_practice_and_Abaqus","question":"When is an axisymmetric FE model appropriate?","answer":"Geometry, material, and boundary/loading response are rotationally symmetric about an axis.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Geometry, material, and boundary/loading response are rotationally symmetric about an axis.","Small residual alone is insufficient if the model contains rigid-body motion or an ill-conditioned constraint.","For linear limits or simplified configurations where closed-form deflections/rotations are available.","Standard solves coupled equilibrium iteratively; Explicit advances dynamics with small stable steps."],"correct":0},{"id":"c335","topic":"13_Exam_practice_and_Abaqus","question":"Why does a reduced-integration element need an hourglass check?","answer":"Underintegration can permit zero-energy deformation modes stabilized numerically rather than physically.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Reduced integration can introduce nonphysical zero-energy hourglass modes.","Reduced integration automatically guarantees perfect energy balance.","Hourglass modes appear only in full integration.","Reduced integration eliminates contact and plasticity errors."],"correct":0},{"id":"c336","topic":"13_Exam_practice_and_Abaqus","question":"What is the benefit of reduced integration?","answer":"Lower cost and sometimes less locking, provided hourglass/zero-energy modes are controlled.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Fewer integration points and often lower computational cost.","A guarantee of convergence for any mesh.","No need to check artificial energy.","Exact stress integration for every polynomial field."],"correct":0},{"id":"c337","topic":"13_Exam_practice_and_Abaqus","question":"What is the main risk of excessively coarse meshes near contact or yielding?","answer":"Inaccurate pressure distributions, localization, stress gradients, and predicted load–deflection behavior.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Inaccurate pressure distributions, localization, stress gradients, and predicted load–deflection behavior.","Continue an existing solution path from a stored converged state, potentially with modified step controls.","B23 uses cubic Euler–Bernoulli bending interpolation; B21 is a linear Timoshenko beam including shear effects.","For linear limits or simplified configurations where closed-form deflections/rotations are available."],"correct":0},{"id":"c338","topic":"13_Exam_practice_and_Abaqus","question":"How would you distinguish a numerical instability from physical snap-through?","answer":"Compare refinements, step sizes, energy trends, reactions, and deformation modes.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Compare refinements, step sizes, energy trends, reactions, and deformation modes.","Lower cost and sometimes less locking, provided hourglass/zero-energy modes are controlled.","Unstable equilibrium paths including descending load segments and snap-through.","Define admissible DOFs, write U and Ω with signs, then set first variation to zero."],"correct":0},{"id":"c339","topic":"13_Exam_practice_and_Abaqus","question":"What should an exam derivation of tangent stiffness begin with?","answer":"A clearly defined residual/equilibrium equation followed by consistent differentiation with respect to DOFs.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Define the residual and differentiate internal/external forces.","Start by selecting a stable time step only.","Start by taking the determinant of the mass matrix.","Assume the tangent matrix is identical to the secant."],"correct":0},{"id":"c340","topic":"13_Exam_practice_and_Abaqus","question":"What should an exam derivation from total potential energy begin with?","answer":"Define admissible DOFs, write U and Ω with signs, then set first variation to zero.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Differentiate Π with respect to every independent displacement DOF.","Set Π = 0 and stop without differentiation.","Differentiate the density with respect to load.","Replace all generalized forces with natural frequencies."],"correct":0},{"id":"c341","topic":"13_Exam_practice_and_Abaqus","question":"What is the most useful quantity to compare across nonlinear solution algorithms?","answer":"A converged load–displacement or time-history solution, not iteration count alone.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["A converged load–displacement or time-history solution, not iteration count alone.","More converged points resolve sharp nonlinear changes and critical points.","It enables a geometrically nonlinear formulation that accounts for the deformed configuration.","Compare refinements, step sizes, energy trends, reactions, and deformation modes."],"correct":0},{"id":"c342","topic":"13_Exam_practice_and_Abaqus","question":"What is a typical convergence warning in an FE analysis?","answer":"Small residual alone is insufficient if the model contains rigid-body motion or an ill-conditioned constraint.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Small residual alone is insufficient if the model contains rigid-body motion or an ill-conditioned constraint.","Multiply the reaction from the half model by two when the full model consists of two identical symmetric halves.","A clearly defined residual/equilibrium equation followed by consistent differentiation with respect to DOFs.","Reactions and displacements from the wrong node or reference point can give a plausible but incorrect curve."],"correct":0},{"id":"c343","topic":"13_Exam_practice_and_Abaqus","question":"Why does verifying the correct output set/node matter in Abaqus?","answer":"Reactions and displacements from the wrong node or reference point can give a plausible but incorrect curve.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Reactions and displacements from the wrong node or reference point can give a plausible but incorrect curve.","B23 uses cubic Euler–Bernoulli bending interpolation; B21 is a linear Timoshenko beam including shear effects.","Small residual alone is insufficient if the model contains rigid-body motion or an ill-conditioned constraint.","A clearly defined residual/equilibrium equation followed by consistent differentiation with respect to DOFs."],"correct":0},{"id":"c344","topic":"13_Exam_practice_and_Abaqus","question":"What is the role of a restart analysis in nonlinear FEA?","answer":"Continue an existing solution path from a stored converged state, potentially with modified step controls.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Continue an existing solution path from a stored converged state, potentially with modified step controls.","Small residual alone is insufficient if the model contains rigid-body motion or an ill-conditioned constraint.","A clearly defined residual/equilibrium equation followed by consistent differentiation with respect to DOFs.","A converged load–displacement or time-history solution, not iteration count alone."],"correct":0},{"id":"c345","topic":"13_Exam_practice_and_Abaqus","question":"When should a model be checked against elementary beam theory?","answer":"For linear limits or simplified configurations where closed-form deflections/rotations are available.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["For linear limits or simplified configurations where closed-form deflections/rotations are available.","Standard solves coupled equilibrium iteratively; Explicit advances dynamics with small stable steps.","Underintegration can permit zero-energy deformation modes stabilized numerically rather than physically.","Inaccurate pressure distributions, localization, stress gradients, and predicted load–deflection behavior."],"correct":0},{"id":"c346","topic":"13_Exam_practice_and_Abaqus","question":"What is the simplest way to test a plasticity implementation?","answer":"Use a uniaxial loading–unloading cycle and verify the elastic slope, yield condition, and residual strain.","source":"Lecture 1; Lecture 9; Exercise 1; Exercise 2; Exercise 3; Exercise 4; Exercise 5; Exercise 7; Exercise 9; Exercise 10; Exam 2020 P1-P4; Exam 2023 P3; Exam 2024 P3-P4; Exam 2025 P4","options":["Run a uniaxial load–unload cycle and check yield and permanent strain.","Check only the initial total mass.","Perform solely an eigenvalue buckling analysis.","Disable plasticity and compare rigid-body motions."],"correct":0}];
